import pandas as pd

# Sample DataFrame for demonstration
df = pd.DataFrame({
    'Title': ['Good &AMP; bad', 'Test &LT; value', 'Another &GT; example', 'No entities here'],
    'Description': ['&AMP; at start', 'Middle &LT; part', '&GT; end']
})

# Define the mapping of HTML entities to their characters
entity_map = {
    '&AMP;': '&',
    '&LT;': '<',
    '&GT;': '>'
}

# Apply replacement across all columns in the DataFrame
for col in df.columns:
    if df[col].dtype == 'object':  # Ensure we only process string columns
        for entity, char in entity_map.items():
            df[col] = df[col].str.replace(entity, char, regex=False)

# Display the result
print(df)

