# Sample data
data = {
    'ID': [1, 2, 3, 4, 5],
    'Field1': [1.15, 2, 1, 25, "and"]
}
df = pd.DataFrame(data)

def is_integer_value(val):
    """Check if a value is an integer (including numeric strings that represent integers)."""
    if isinstance(val, bool):
        return False
    if isinstance(val, int):
        return True
    if isinstance(val, float):
        # Check if the float is actually an integer (e.g., 2.0)
        return val.is_integer()
    if isinstance(val, str):
        try:
            # Try to convert string to float first to handle "1.0" or "2"
            f_val = float(val)
            return f_val.is_integer() and '.' not in val  # Ensure it doesn't look like a float string
        except ValueError:
            return False
    return False

error_values = []

# Iterate over the 'Field1' column directly to avoid iterrows type conversion issues
for idx, value in df['Field1'].items():
    if not is_integer_value(value):
        error_values.append(value)

print(error_values)

