import pandas as pd
import numpy as np

# Sample data
data = {
    'ID': [1, 2, 3, 4, 5],
    'Field1': [1.15, 2, 1, 25, "and"]
}
df = pd.DataFrame(data)

def is_integer_value(val):
    """Check if a value is an integer (including integer-like floats)."""
    if isinstance(val, bool):
        return False
    if isinstance(val, int):
        return True
    if isinstance(val, float):
        # Check if it's a whole number and not NaN/Inf
        if np.isnan(val) or np.isinf(val):
            return False
        return val.is_integer()
    if isinstance(val, str):
        try:
            # Try to convert string to int
            float_val = float(val)
            if float_val.is_integer():
                return True
            return False
        except ValueError:
            return False
    return False

error_values = []

for idx, row in df.iterrows():
    val = row['Field1']
    if not is_integer_value(val):
        error_values.append(val)

print(error_values)

