import pandas as pd
import numpy as np

# Create the DataFrame
data = {
    'a': [1, 1, 1, 2, 2, 2, 3, 3, 3],
    'b': [12, 13, 23, 22, 23, 24, 30, 35, 55]
}
df = pd.DataFrame(data)

# Define softmax function for a group
def softmax(x):
    e_x = np.exp(x - np.max(x))  # Subtract max for numerical stability
    return e_x / e_x.sum()

# Define min-max normalization function for a group
def min_max_norm(x):
    x_min = x.min()
    x_max = x.max()
    if x_max == x_min:
        return pd.Series([0.0] * len(x), index=x.index)
    return (x - x_min) / (x_max - x_min)

# Apply groupby transformations
df['softmax'] = df.groupby('a')['b'].transform(softmax)
df['min-max'] = df.groupby('a')['b'].transform(min_max_norm)

# Display the result
print(df)

