def find_relative_extrema(arr, n=2):
    """
    Find indices of relative extrema in an array.

    An element is a relative extrema if it is less than or equal to the 
    neighbouring n elements forwards and backwards.

    Parameters:
    arr (list): The input array of numbers.
    n (int): The number of neighbours to check on each side.

    Returns:
    list: Indices of relative extrema in original order.
    """
    if not arr or n < 0:
        return []

    indices = []
    length = len(arr)

    for i in range(length):
        is_extrema = True

        # Check backwards neighbours
        for j in range(1, n + 1):
            if i - j >= 0:
                if arr[i] > arr[i - j]:
                    is_extrema = False
                    break

        if not is_extrema:
            continue

        # Check forwards neighbours
        for j in range(1, n + 1):
            if i + j < length:
                if arr[i] > arr[i + j]:
                    is_extrema = False
                    break

        if is_extrema:
            indices.append(i)

    return indices

# Example usage:
if __name__ == "__main__":
    data = [5, 3, 4, 2, 1, 3, 2, 4, 6]
    result = find_relative_extrema(data, n=2)
    print(f"Indices of relative extrema: {result}")
    # Expected output based on logic: indices where element <= neighbours within range n=2

