import csv
import sys

def read_csv_file(filename):
    """Reads a CSV file and returns headers and rows as lists of strings."""
    with open(filename, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        headers = next(reader)
        rows = []
        for row in reader:
            rows.append(row)
    return headers, rows

def count_values(rows, col_index):
    """Manually counts occurrences of each value in a specific column index."""
    counts = {}
    for row in rows:
        if col_index < len(row):
            val = row[col_index]
        else:
            val = ""

        # Handle empty strings as 'null' for consistency with the example
        if val == "":
            val = "null"

        if val in counts:
            counts[val] = counts[val] + 1
        else:
            counts[val] = 1

    return counts

def sort_counts_manually(counts_dict):
    """Sorts a dictionary by value (count) descending, then by key ascending."""
    # Convert dict to list of tuples manually
    items_list = []
    for k in counts_dict:
        items_list.append((k, counts_dict[k]))

    # Bubble sort implementation
    n = len(items_list)
    for i in range(n):
        for j in range(0, n - i - 1):
            # Primary sort: count descending
            if items_list[j][1] < items_list[j + 1][1]:
                temp = items_list[j]
                items_list[j] = items_list[j + 1]
                items_list[j + 1] = temp
            # Secondary sort: key ascending (if counts are equal)
            elif items_list[j][1] == items_list[j + 1][1]:
                if items_list[j][0] > items_list[j + 1][0]:
                    temp = items_list[j]
                    items_list[j] = items_list[j + 1]
                    items_list[j + 1] = temp

    return items_list

def infer_dtype(values_list):
    """Attempts to infer a simple dtype string based on content."""
    if not values_list:
        return "object"

    # Check if all are integers
    is_int = True
    for val in values_list:
        if val == "null":
            continue
        try:
            int(val)
        except ValueError:
            is_int = False
            break

    if is_int:
        return "int64"

    # Check if all are floats
    is_float = True
    for val in values_list:
        if val == "null":
            continue
        try:
            float(val)
        except ValueError:
            is_float = False
            break

    if is_float:
        return "float64"

    return "object"

def generate_value_counts_report(filename):
    """Generates the full report string."""
    headers, rows = read_csv_file(filename)

    output_lines = []

    for i in range(len(headers)):
        col_name = headers[i]

        # Get counts for this column
        raw_counts = count_values(rows, i)

        # Sort the counts
        sorted_items = sort_counts_manually(raw_counts)

        # Infer dtype based on unique values found
        unique_vals = []
        for item in sorted_items:
            unique_vals.append(item[0])
        dtype_str = infer_dtype(unique_vals)

        # Build output block
        output_lines.append("---- " + col_name + " ---")

        for item in sorted_items:
            val, count = item
            output_lines.append(str(val) + "    " + str(count))

        output_lines.append("Name: " + col_name + ", dtype: " + dtype_str)
        output_lines.append("") # Empty line between columns

    return "\n".join(output_lines)

# Main execution block
if __name__ == "__main__":
    # Check if filename is provided as argument, otherwise default to 'data.csv'
    if len(sys.argv) > 1:
        input_file = sys.argv[1]
    else:
        input_file = "data.csv"

    try:
        report = generate_value_counts_report(input_file)
        print(report)
    except FileNotFoundError:
        print("Error: File not found. Please provide a valid CSV filename.")
    except Exception as e:
        print("An error occurred: " + str(e))

