import math

def sigmoid(x):
    return 1.0 / (1.0 + math.exp(-x))

class SimpleDataFrame:
    def __init__(self, data_dict):
        self.data = {}
        self.columns = []
        for key in data_dict:
            self.columns.append(key)
            self.data[key] = list(data_dict[key])

    def get_column(self, col_name):
        return self.data[col_name]

    def set_column(self, col_name, values):
        self.data[col_name] = values
        if col_name not in self.columns:
            self.columns.append(col_name)

    def to_dict(self):
        result = {}
        for col in self.columns:
            result[col] = list(self.data[col])
        return result

def add_sigmoid_columns(df_obj):
    new_df = SimpleDataFrame({})

    # Copy existing columns
    for col in df_obj.columns:
        original_values = df_obj.get_column(col)
        new_df.set_column(col, original_values)

        # Calculate sigmoid values manually
        sigmoid_values = []
        i = 0
        while i < len(original_values):
            val = original_values[i]
            sig_val = sigmoid(val)
            sigmoid_values.append(sig_val)
            i = i + 1

        # Add new column with prefix
        new_col_name = "sigmoid_" + col
        new_df.set_column(new_col_name, sigmoid_values)

    return new_df

