def parse_date(date_str):
    parts = date_str.split('-')
    year = int(parts[0])
    month = int(parts[1])
    day = int(parts[2])
    return (year, month, day)

def format_date(year, month, day):
    return "{:04d}-{:02d}-{:02d}".format(year, month, day)

def is_leap_year(year):
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    if year % 400 != 0:
        return False
    return True

def days_in_month(year, month):
    if month == 2:
        if is_leap_year(year):
            return 29
        else:
            return 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def add_days_to_date(year, month, day, days_to_add):
    current_year = year
    current_month = month
    current_day = day

    while days_to_add > 0:
        days_in_current_month = days_in_month(current_year, current_month)
        remaining_in_month = days_in_current_month - current_day

        if days_to_add <= remaining_in_month:
            current_day += days_to_add
            days_to_add = 0
        else:
            days_to_add -= (remaining_in_month + 1)
            current_day = 1
            current_month += 1
            if current_month > 12:
                current_month = 1
                current_year += 1

    return (current_year, current_month, current_day)

def date_diff(date1_tuple, date2_tuple):
    # Returns number of days from date1 to date2
    y1, m1, d1 = date1_tuple
    y2, m2, d2 = date2_tuple

    if (y1, m1, d1) == (y2, m2, d2):
        return 0

    # Simple approach: iterate day by day from start to end
    count = 0
    curr_y, curr_m, curr_d = y1, m1, d1

    while (curr_y, curr_m, curr_d) != (y2, m2, d2):
        days_in_curr = days_in_month(curr_y, curr_m)
        if curr_d < days_in_curr:
            curr_d += 1
        else:
            curr_d = 1
            curr_m += 1
            if curr_m > 12:
                curr_m = 1
                curr_y += 1
        count += 1

    return count

def process_dataframe(data_rows):
    # data_rows is a list of lists: [['user', 'dt', 'val'], [row1], [row2], ...]
    # Extract headers and data
    if len(data_rows) < 2:
        return []

    headers = data_rows[0]
    rows = data_rows[1:]

    # Find min and max date across all rows
    min_date_tuple = None
    max_date_tuple = None

    for row in rows:
        dt_str = row[1]
        dt_tuple = parse_date(dt_str)

        if min_date_tuple is None:
            min_date_tuple = dt_tuple
            max_date_tuple = dt_tuple
        else:
            # Compare with min
            if date_diff(min_date_tuple, dt_tuple) > 0:
                min_date_tuple = dt_tuple
            # Compare with max
            if date_diff(dt_tuple, max_date_tuple) > 0:
                max_date_tuple = dt_tuple

    # Get unique users
    unique_users = []
    for row in rows:
        user = row[0]
        is_new = True
        for existing_user in unique_users:
            if existing_user == user:
                is_new = False
                break
        if is_new:
            unique_users.append(user)

    # Create a lookup map for existing values: (user, date_str) -> val
    value_map = {}
    for row in rows:
        user = row[0]
        dt_str = row[1]
        val = int(row[2])
        key = (user, dt_str)
        value_map[key] = val

    # Generate result
    result_rows = []

    for user in unique_users:
        current_date_tuple = min_date_tuple

        while True:
            current_date_str = format_date(current_date_tuple[0], current_date_tuple[1], current_date_tuple[2])

            key = (user, current_date_str)
            if key in value_map:
                val = value_map[key]
            else:
                val = 0

            result_rows.append([current_date_str, user, val])

            # Check if we reached max date
