def parse_date(date_str):
    parts = date_str.split('-')
    year = int(parts[0])
    month = int(parts[1])
    day = int(parts[2])
    return (year, month, day)

def format_date(year, month, day):
    return "{:04d}-{:02d}-{:02d}".format(year, month, day)

def add_days_to_date(year, month, day, days_to_add):
    # Simple implementation assuming no leap years for simplicity in this context
    # and handling month rollovers manually.
    # Days in months (non-leap year)
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    day += days_to_add

    while day > days_in_months[month - 1]:
        day -= days_in_months[month - 1]
        month += 1
        if month > 12:
            month = 1
            year += 1

    return (year, month, day)

def compare_dates(d1, d2):
    # Returns negative if d1 < d2, positive if d1 > d2, 0 if equal
    if d1[0] != d2[0]:
        return d1[0] - d2[0]
    if d1[1] != d2[1]:
        return d1[1] - d2[1]
    return d1[2] - d2[2]

def get_min_date(date_list):
    if not date_list:
        return None
    min_d = date_list[0]
    for i in range(1, len(date_list)):
        if compare_dates(date_list[i], min_d) < 0:
            min_d = date_list[i]
    return min_d

def get_max_date(date_list):
    if not date_list:
        return None
    max_d = date_list[0]
    for i in range(1, len(date_list)):
        if compare_dates(date_list[i], max_d) > 0:
            max_d = date_list[i]
    return max_d

def days_between(d1, d2):
    # Calculate difference in days between two dates (d2 - d1)
    # Assuming d2 >= d1 for this logic
    y1, m1, day1 = d1
    y2, m2, day2 = d2

    # Convert to absolute days from a reference point (e.g., year 0)
    # This is a simplified calculation ignoring leap years for consistency with add_days_to_date
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    total_days_1 = y1 * 365 + sum(days_in_months[:m1-1]) + day1
    total_days_2 = y2 * 365 + sum(days_in_months[:m2-1]) + day2

    return total_days_2 - total_days_1

