def replace_html_entities_in_dataframe(df):
    """
    Replaces HTML entities (&AMP;, &LT;, &GT;) with their corresponding characters
    in all string columns of a DataFrame-like structure (list of lists or list of dicts).
    This implementation does not use pandas, numpy, or any external libraries.
    It manually iterates through data and performs string replacements.
    """

    # Define the mapping of entities to characters
    entity_map = {
        "&AMP;": "&",
        "&LT;": "<",
        "&GT;": ">"
    }

    # Helper function to replace entities in a single string
    def clean_string(text):
        if not isinstance(text, str):
            return text

        result_chars = []
        i = 0
        length = len(text)

        while i < length:
            matched = False
            for entity, char in entity_map.items():
                entity_len = len(entity)
                # Check if the substring starting at i matches the entity
                if i + entity_len <= length:
                    potential_match = ""
                    k = 0
                    while k < entity_len:
                        potential_match += text[i + k]
                        k += 1

                    if potential_match == entity:
                        result_chars.append(char)
                        i += entity_len
                        matched = True
                        break

            if not matched:
                result_chars.append(text[i])
                i += 1

        return "".join(result_chars)

    # Helper function to process a single row (dict or list)
    def clean_row(row):
        if isinstance(row, dict):
            cleaned_row = {}
            for key in row:
                value = row[key]
                if isinstance(value, str):
                    cleaned_row[key] = clean_string(value)
                else:
                    cleaned_row[key] = value
            return cleaned_row
        elif isinstance(row, list):
            cleaned_row = []
            for item in row:
                if isinstance(item, str):
                    cleaned_row.append(clean_string(item))
                else:
                    cleaned_row.append(item)
            return cleaned_row
        else:
            return row

    # Process the entire dataframe structure
    if not df:
        return df

    # Determine if input is list of dicts or list of lists based on first element
    first_item = df[0]

    if isinstance(first_item, dict):
        result = []
        for row in df:
            result.append(clean_row(row))
        return result
    elif isinstance(first_item, list):
        result = []
        for row in df:
            result.append(clean_row(row))
        return result
    else:
        # If it's a single value or unexpected format, try to clean it directly
        if isinstance(df, str):
            return clean_string(df)
        return df

