    for row in data:
        key = row[group_col]
        if key not in groups:
            groups[key] = []
        groups[key].append(row[value_col])

    result_rows = []

    # Second pass: calculate sums for each group
    for key in groups:
        values = groups[key]
        current_sum = 0.0
        has_nan = False

        for val in values:
            if is_nan(val):
                has_nan = True
                break
            else:
                current_sum = current_sum + val

        if has_nan:
            final_value = float('nan')
        else:
            final_value = current_sum

        result_rows.append({group_col: key, value_col: final_value})

    return result_rows

# Setup data manually to avoid pandas/numpy imports for the logic part
