def determine_relationship(col_a, col_b):
    """
    Determines the relationship type between two columns.
    Returns: 'one-to-one', 'one-to-many', 'many-to-one', or 'many-to-many'

    Logic:
    - one-to-one: Each value in A maps to exactly one unique value in B, 
                  and each value in B maps to exactly one unique value in A.
    - one-to-many: Each value in A maps to multiple values in B (at least one does),
                   but each value in B maps to only one value in A.
    - many-to-one: Each value in A maps to only one value in B,
                   but at least one value in B maps to multiple values in A.
    - many-to-many: At least one value in A maps to multiple values in B,
                    AND at least one value in B maps to multiple values in A.
    """

    # Build mapping from A -> set of B values
    map_a_to_b = {}
    for i in range(len(col_a)):
        val_a = col_a[i]
        val_b = col_b[i]
        if val_a not in map_a_to_b:
            map_a_to_b[val_a] = []
        map_a_to_b[val_a].append(val_b)

    # Build mapping from B -> set of A values
    map_b_to_a = {}
    for i in range(len(col_a)):
        val_a = col_a[i]
        val_b = col_b[i]
        if val_b not in map_b_to_a:
            map_b_to_a[val_b] = []
        map_b_to_a[val_b].append(val_a)

    # Check uniqueness from A to B
    a_is_unique = True
    for key in map_a_to_b:
        unique_vals = []
        seen = False
        for item in map_a_to_b[key]:
            is_new = True
            for existing in unique_vals:
                if item == existing:
                    is_new = False
                    break
            if is_new:
                unique_vals.append(item)

        if len(unique_vals) > 1:
            a_is_unique = False
            break

    # Check uniqueness from B to A
    b_is_unique = True
    for key in map_b_to_a:
        unique_vals = []
        for item in map_b_to_a[key]:
            is_new = True
            for existing in unique_vals:
                if item == existing:
                    is_new = False
                    break
            if is_new:
                unique_vals.append(item)

        if len(unique_vals) > 1:
            b_is_unique = False
            break

    if a_is_unique and b_is_unique:
        return "one-to-one"
    elif a_is_unique and not b_is_unique:
        return "many-to-one"
    elif not a_is_unique and b_is_unique:
        return "one-to-many"
    else:
        return "many-to-many"


def create_relationship_matrix(data_dict):
    """
    Creates a relationship matrix for all pairs of columns in the data dictionary.
    Returns a list of lists representing the matrix, where diagonal is None (NaN).
    """
    keys = []
    for k in data_dict:
        keys.append(k)

    n = len(keys)
    result_matrix = []

    # Initialize matrix with None
    for i in range(n):
        row = []
        for j in range(n):
            row.append(None)
        result_matrix.append(row)

    # Fill the matrix
    for i in range(n):
        for j in range(n):
            if i == j:
                continue

            col_a = data_dict[keys[i]]
            col_b = data_dict[keys[j]]

            rel_type = determine_relationship(col_a, col_b)
            result_matrix[i][j] = rel_type

    return keys, result_matrix


def print_matrix(keys, matrix):
    """
    Prints the relationship matrix in a formatted way.
    """
    # Calculate column widths
    max_key_len = 0
    for k in keys:
        if len(k) > max_key_len:
            max_key_len = len(k)

    # Header row
    header = "             "
    for k in keys:
        header += k.ljust(max_key_len + 2)
    print(header)

    # Data rows
