def determine_relationship(col_a, col_b):
    # Count unique values in each column
    unique_a = get_unique_count(col_a)
    unique_b = get_unique_count(col_b)

    # Check mapping from A to B (for each value in A, how many distinct values in B?)
    # We need to check if any value in A maps to multiple values in B
    a_to_b_is_many = False
    len_a = len(col_a)

    for i in range(len_a):
        val_a = col_a[i]
        mapped_values_b = []

        # Find all b values associated with this specific a value
        for j in range(len_a):
            if col_a[j] == val_a:
                mapped_values_b.append(col_b[j])

        # Check uniqueness of mapped b values
        unique_mapped_b = get_unique_count(mapped_values_b)
        if unique_mapped_b > 1:
            a_to_b_is_many = True
            break

    # Check mapping from B to A (for each value in B, how many distinct values in A?)
    b_to_a_is_many = False

    for i in range(len_a):
        val_b = col_b[i]
        mapped_values_a = []

        # Find all a values associated with this specific b value
        for j in range(len_a):
            if col_b[j] == val_b:
                mapped_values_a.append(col_a[j])

        # Check uniqueness of mapped a values
        unique_mapped_a = get_unique_count(mapped_values_a)
        if unique_mapped_a > 1:
            b_to_a_is_many = True
            break

    # Determine relationship type
    # A -> B is One-to-One if not many, Many-to-One if many
    # B -> A is One-to-One if not many, Many-to-One if many

    # Relationship from perspective of (A, B) pair:
    # If A->B is one and B->A is one: one-2-one
    # If A->B is one and B->A is many: one-2-many
    # If A->B is many and B->A is one: many-2-one
    # If A->B is many and B->A is many: many-2-many

    if not a_to_b_is_many and not b_to_a_is_many:
        return "one-2-one"
    elif not a_to_b_is_many and b_to_a_is_many:
