    i = len(lst) - 1
    while i >= 0:
        result.append(lst[i])
        i = i - 1
    return result

def convert_to_int(value):
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return value
    return value

def process_dataframe_column(data_list, column_name):
    # data_list is a list of dictionaries representing rows
    # column_name is the string name of the column containing lists

    all_reversed_items = []

    for row in data_list:
        raw_value = row[column_name]

        if isinstance(raw_value, str):
            # Handle case where the list is stored as a string like "[1, 2, 3]"
            cleaned_str = raw_value.strip()
            if cleaned_str.startswith('[') and cleaned_str.endswith(']'):
                inner_content = cleaned_str[1:-1]
                if len(inner_content) == 0:
                    current_list = []
                else:
                    parts = []
                    current_part = ""
                    for char in inner_content:
                        if char == ',':
                            parts.append(current_part.strip())
                            current_part = ""
                        else:
                            current_part += char
                    if current_part:
                        parts.append(current_part.strip())

                    current_list = []
                    for part in parts:
                        current_list.append(convert_to_int(part))
            else:
                # Fallback if string is not a list representation
                current_list = [convert_to_int(raw_value)]
        elif isinstance(raw_value, list):
            current_list = []
            for item in raw_value:
                current_list.append(convert_to_int(item))
        else:
            current_list = [convert_to_int(raw_value)]

        reversed_current = reverse_list(current_list)

        for item in reversed_current:
            all_reversed_items.append(str(item))

    result_string = ""
    i = 0
    while i < len(all_reversed_items):
        if i > 0:
            result_string += ","
        result_string += all_reversed_items[i]
        i = i + 1

    return result_string

