import math

def calculate_mean(data):
    total = 0.0
    count = 0
    for value in data:
        total += value
        count += 1
    if count == 0:
        return 0.0
    return total / count

def calculate_variance(data, mean_value):
    sum_squared_diff = 0.0
    count = 0
    for value in data:
        diff = value - mean_value
        sum_squared_diff += diff * diff
        count += 1
    if count == 0:
        return 0.0
    # Using population variance (dividing by N) as is standard for "sigma" of a dataset unless specified otherwise
    return sum_squared_diff / count

def calculate_std_dev(data):
    mean_val = calculate_mean(data)
    var_val = calculate_variance(data, mean_val)
    return math.sqrt(var_val)

def get_three_sigma_interval(data):
    if not data:
        return (0.0, 0.0)

    mu = calculate_mean(data)
    sigma = calculate_std_dev(data)

    lower_bound = mu - (3 * sigma)
    upper_bound = mu + (3 * sigma)

    return (lower_bound, upper_bound)

