def zero_out_rows_and_cols(matrix, zero_rows, zero_cols):
    # Create a deep copy of the matrix manually to avoid modifying the original
    rows = len(matrix)
    if rows == 0:
        return []

    cols = len(matrix[0])
    result = []

    for i in range(rows):
        new_row = []
        for j in range(cols):
            new_row.append(matrix[i][j])
        result.append(new_row)

    # Zero out specified rows
    for r_idx in zero_rows:
        if 0 <= r_idx < rows:
            for c in range(cols):
                result[r_idx][c] = 0

    # Zero out specified columns
    for c_idx in zero_cols:
        if 0 <= c_idx < cols:
            for r in range(rows):
                result[r][c_idx] = 0

    return result

