def create_min_mask(arr, axis):
    """
    Creates a boolean mask where the minimum value along the specified axis is True.

    Parameters:
    arr (list of lists): 2D input array represented as nested lists.
    axis (int): The axis along which to find the minimum (0 for columns, 1 for rows).

    Returns:
    list of lists: A boolean mask with the same dimensions as the input.
    """
    if not arr or not arr[0]:
        return []

    num_rows = len(arr)
    num_cols = len(arr[0])

    # Initialize result mask with False
    mask = []
    for r in range(num_rows):
        row_mask = []
        for c in range(num_cols):
            row_mask.append(False)
        mask.append(row_mask)

    if axis == 1:
        # Find min along each row (axis 1)
        for r in range(num_rows):
            # Find minimum value in the current row manually
            min_val = arr[r][0]
            for c in range(1, num_cols):
                if arr[r][c] < min_val:
                    min_val = arr[r][c]

            # Set True for positions matching the minimum
            for c in range(num_cols):
                if arr[r][c] == min_val:
                    mask[r][c] = True

    elif axis == 0:
        # Find min along each column (axis 0)
        for c in range(num_cols):
            # Find minimum value in the current column manually
            min_val = arr[0][c]
            for r in range(1, num_rows):
                if arr[r][c] < min_val:
                    min_val = arr[r][c]

            # Set True for positions matching the minimum
            for r in range(num_rows):
                if arr[r][c] == min_val:
                    mask[r][c] = True

    return mask

