def manual_l1_normalize(matrix):
    if not matrix:
        return []

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    # Calculate L1 norm for each row manually
    norms = []
    for i in range(num_rows):
        current_sum = 0.0
        for j in range(num_cols):
            val = matrix[i][j]
            if val < 0:
                current_sum += -val
            else:
                current_sum += val
        norms.append(current_sum)

    # Normalize each row manually
    result = []
    for i in range(num_rows):
        new_row = []
        norm_val = norms[i]
        if norm_val == 0.0:
            # If norm is zero, keep the row as zeros to avoid division by zero
            for j in range(num_cols):
                new_row.append(0.0)
        else:
            for j in range(num_cols):
                new_row.append(matrix[i][j] / norm_val)
        result.append(new_row)

    return result

