            try:
                value = float(item)
            except ValueError:
                continue

            if math.isinf(value):
                has_inf = True
                total_sum += value
                count += 1
            else:
                total_sum += value
                count += 1
        elif isinstance(item, (int, float)):
            if math.isinf(item):
                has_inf = True
                total_sum += item
                count += 1
            else:
                total_sum += item
                count += 1

    if count == 0:
