    flat_values = []
    for row in data:
        for val in row:
            flat_values.append(val)

    # Find global minimum manually
    global_min = flat_values[0]
    for i in range(1, len(flat_values)):
        if flat_values[i] < global_min:
            global_min = flat_values[i]

    # Find global maximum manually
    global_max = flat_values[0]
    for i in range(1, len(flat_values)):
