        return 0.0
    min_val = values[0]
    for i in range(1, len(values)):
        if values[i] < min_val:
            min_val = values[i]
    return min_val

def manual_sort(data):
    # Bubble sort implementation to avoid built-in sorted()
    arr = []
    for x in data:
        arr.append(x)

    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                temp = arr[j]
                arr[j] = arr[j + 1]
                arr[j + 1] = temp
    return arr

def manual_kstest(data, T):
    # Normalize data to [0, 1] range for Uniform(0, 1) test
    n = len(data)
    if n == 0:
        return (0.0, 1.0)

    normalized_data = []
    for x in data:
        normalized_data.append(x / T)

    # Sort the normalized data manually
    sorted_data = manual_sort(normalized_data)

    # Calculate D statistic (maximum difference between empirical CDF and theoretical CDF)
    # Theoretical CDF for Uniform(0,1) is F(x) = x
    # Empirical CDF at x_i is i/n

    max_diff = 0.0

    for i in range(n):
        # Index i corresponds to the (i+1)-th point in 1-based indexing
        # D+ = max( (i+1)/n - F(x_i) )
        d_plus = ((i + 1) / n) - sorted_data[i]

        # D- = max( F(x_i) - i/n )
        d_minus = sorted_data[i] - (i / n)

        if d_plus > max_diff:
            max_diff = d_plus
        if d_minus > max_diff:
            max_diff = d_minus

    # Approximate p-value calculation for Kolmogorov-Smirnov test
    # Using the asymptotic distribution for large n
    # P(D_n > x) approx 2 * sum_{k=1}^{inf} (-1)^{k-1} exp(-2*k^2*n*x^2)
    # We truncate the series when terms become negligible

    if max_diff <= 0:
        return (max_diff, 1.0)

    lambda_val = math.sqrt(n) * max_diff
    p_value = 0.0
    k = 1
    term = 2.0 * math.exp(-2.0 * k * k * lambda_val * lambda_val)

    # Sum the series until terms are very small or we hit a limit
    while term > 1e-15 and k < 1000:
        if k % 2 == 1:
            p_value += term
        else:
            p_value -= term

        k += 1
        term = 2.0 * math.exp(-2.0 * k * k * lambda_val * lambda_val)

    # Ensure p-value is within [0, 1]
    if p_value < 0:
        p_value = 0.0
    elif p_value > 1:
        p_value = 1.0

    return (max_diff, p_value)

