def remove_isolated_cells(binary_array):
    """
    Removes completely isolated single cells (value 1) from a 2D binary array.
    A cell is considered isolated if it is 1 and all its 8 neighbors are 0.

    This implementation uses only standard Python loops and no external libraries.
    It handles edge cases where the array has fewer than 3 rows or columns.
    """
    # Handle empty arrays or arrays too small to have neighbors
    if not binary_array:
        return []

    num_rows = len(binary_array)
    if num_rows == 0:
        return []

    num_cols = len(binary_array[0])
    if num_cols == 0:
        return []

    # If the array is too small to have a center cell with 8 neighbors, 
    # no cell can be "completely surrounded" in the 3x3 sense defined.
    if num_rows < 3 or num_cols < 3:
        # Return a copy of the original array since no changes are possible
        result = []
        for r in range(num_rows):
            row_copy = []
            for c in range(num_cols):
                row_copy.append(binary_array[r][c])
            result.append(row_copy)
        return result

    # Create a deep copy of the array to store the result
    result = []
    for r in range(num_rows):
        row_copy = []
        for c in range(num_cols):
            row_copy.append(binary_array[r][c])
        result.append(row_copy)

    # Iterate through the inner cells (excluding the border)
    # Border cells cannot be completely surrounded by 8 neighbors within the array bounds
    for r in range(1, num_rows - 1):
        for c in range(1, num_cols - 1):
            if binary_array[r][c] == 1:
                # Check all 8 neighbors manually
                is_isolated = True

                # Top row of neighbors
                if binary_array[r - 1][c - 1] == 1 or binary_array[r - 1][c] == 1 or binary_array[r - 1][c + 1] == 1:
                    is_isolated = False
                # Middle row of neighbors (left and right)
                elif binary_array[r][c - 1] == 1 or binary_array[r][c + 1] == 1:
                    is_isolated = False
                # Bottom row of neighbors
                elif binary_array[r + 1][c - 1] == 1 or binary_array[r + 1][c] == 1 or binary_array[r + 1][c + 1] == 1:
                    is_isolated = False

                if is_isolated:
                    result[r][c] = 0

    return result

import math

def get_unique_ids(raster):
    unique_ids = []
    rows = len(raster)
    if rows == 0:
        return unique_ids

    cols = len(raster[0])

    for r in range(rows):
        for c in range(cols):
            val = raster[r][c]
            found = False
            for existing_id in unique_ids:
                if existing_id == val:
                    found = True
                    break
            if not found:
                unique_ids.append(val)

    return unique_ids

def get_coordinates_for_id(raster, target_id):
    coords = []
    rows = len(raster)
    if rows == 0:
        return coords

    cols = len(raster[0])

    for r in range(rows):
        for c in range(cols):
            if raster[r][c] == target_id:
                coords.append((r, c))

    return coords

def calculate_min_distance_between_ids(raster, id1, id2):
    coords1 = get_coordinates_for_id(raster, id1)
    coords2 = get_coordinates_for_id(raster, id2)

    if not coords1 or not coords2:
        return float('inf')

    min_dist_sq = float('inf')

    for r1, c1 in coords1:
        for r2, c2 in coords2:
            dr = r1 - r2
            dc = c1 - c2
            dist_sq = dr * dr + dc * dc

            if dist_sq < min_dist_sq:
                min_dist_sq = dist_sq

    return math.sqrt(min_dist_sq)

def calculate_pairwise_distances(raster):
    unique_ids = get_unique_ids(raster)

    # Filter out background (0) if desired, but keeping it as per request for all regions
    # If you want to exclude 0, uncomment the next line:
    # unique_ids = [x for x in unique_ids if x != 0]

    n = len(unique_ids)
    results = []

    for i in range(n):
        id_a = unique_ids[i]
        for j in range(i + 1, n):
            id_b = unique_ids[j]

            dist = calculate_min_distance_between_ids(raster, id_a, id_b)

            # Store as tuple: (from_id, to_id, distance)
            results.append((id_a, id_b, dist))

    return results

