import math

def calculate_mean(values):
    total = 0.0
    count = 0
    for val in values:
        if isinstance(val, (int, float)):
            total += val
            count += 1
    if count == 0:
        return 0.0
    return total / count

def calculate_std(values, mean_val):
    sum_sq_diff = 0.0
    count = 0
    for val in values:
        if isinstance(val, (int, float)):
            diff = val - mean_val
            sum_sq_diff += diff * diff
            count += 1
    if count <= 1:
        return 0.0
    variance = sum_sq_diff / count
    return math.sqrt(variance)

def calculate_zscore(value, mean_val, std_val):
    if std_val == 0:
        return 0.0
    return (value - mean_val) / std_val

def is_numeric_column(data_rows, col_index):
    for row in data_rows:
        val = row[col_index]
        if not isinstance(val, (int, float)):
            return False
    return True

def filter_outliers(data_rows, threshold=3.0):
    if not data_rows:
        return []

    num_cols = len(data_rows[0])
    numeric_indices = []

    # Identify numeric columns
    for i in range(num_cols):
        if is_numeric_column(data_rows, i):
            numeric_indices.append(i)

    # Calculate mean and std for each numeric column
    col_stats = {}
    for idx in numeric_indices:
        col_values = []
        for row in data_rows:
            val = row[idx]
            if isinstance(val, (int, float)):
                col_values.append(val)

        mean_val = calculate_mean(col_values)
        std_val = calculate_std(col_values, mean_val)
        col_stats[idx] = {'mean': mean_val, 'std': std_val}

    # Filter rows
    filtered_rows = []
    for row in data_rows:
        is_outlier = False
        for idx in numeric_indices:
            val = row[idx]
            if isinstance(val, (int, float)):
                stats = col_stats[idx]
                z = calculate_zscore(val, stats['mean'], stats['std'])
                if abs(z) > threshold:
                    is_outlier = True
                    break

        if not is_outlier:
            filtered_rows.append(row)

    return filtered_rows

