import math
import random

def sigmoid(z):
    if z >= 0:
        return 1.0 / (1.0 + math.exp(-z))
    else:
        exp_z = math.exp(z)
        return exp_z / (1.0 + exp_z)

def dot_product(v1, v2):
    result = 0.0
    for i in range(len(v1)):
        result += v1[i] * v2[i]
    return result

def add_vectors(v1, v2):
    result = []
    for i in range(len(v1)):
        result.append(v1[i] + v2[i])
    return result

def multiply_vector_scalar(v, s):
    result = []
    for val in v:
        result.append(val * s)
    return result

def subtract_vectors(v1, v2):
    result = []
    for i in range(len(v1)):
        result.append(v1[i] - v2[i])
    return result

def initialize_weights(n_features):
    weights = []
    for _ in range(n_features):
        weights.append(0.0)
    bias = 0.0
    return weights, bias

def train_logistic_regression(X_train, y_train, learning_rate=0.1, n_iterations=1000):
    n_samples = len(X_train)
    n_features = len(X_train[0])

    weights, bias = initialize_weights(n_features)

    for _ in range(n_iterations):
        dw = [0.0] * n_features
        db = 0.0

        for i in range(n_samples):
            x_i = X_train[i]
            y_i = y_train[i]

            z = dot_product(weights, x_i) + bias
            y_pred = sigmoid(z)

            error = y_pred - y_i

            for j in range(n_features):
                dw[j] += error * x_i[j]
            db += error

        for j in range(n_features):
            weights[j] -= learning_rate * (dw[j] / n_samples)
        bias -= learning_rate * (db / n_samples)

    return weights, bias

def predict_proba_single(weights, bias, x):
    z = dot_product(weights, x) + bias
    prob_positive = sigmoid(z)
    prob_negative = 1.0 - prob_positive
    return [prob_negative, prob_positive]

def k_fold_split_indices(n_samples, k):
    indices = []
    for i in range(n_samples):
        indices.append(i)

    fold_size = n_samples // k
    remainder = n_samples % k

    folds = []
    start_idx = 0

    for i in range(k):
        current_fold_size = fold_size + (1 if i < remainder else 0)
        end_idx = start_idx + current_fold_size

        fold_indices = []
        for j in range(start_idx, end_idx):
            fold_indices.append(indices[j])

        folds.append(fold_indices)
        start_idx = end_idx

    return folds

def cross_validate_predict_proba(X, y, k=5, learning_rate=0.1, n_iterations=1000):
    n_samples = len(X)

    if k > n_samples:
        k = n_samples

    fold_indices = k_fold_split_indices(n_samples, k)

    all_predictions = []

    for i in range(k):
        test_indices = fold_indices[i]

        train_indices = []
        for j in range(k):
            if i != j:
                for idx in fold_indices[j]:
                    train_indices.append(idx)

        X_train = []
        y_train = []
        X_test = []
        y_test = []

        for idx in train_indices:
            X_train.append(X[idx])
            y_train.append(y[idx])

        for idx in test_indices:
            X_test.append(X[idx])
            y_test.append(y[idx])

        weights, bias = train_logistic_regression(X_train, y_train, learning_rate, n_iterations)

        for i_test in range(len(X_test)):
            x_sample = X_test[i_test]
            probs = predict_proba_single(weights, bias, x_sample)
            all_predictions.append(probs)

    return all_predictions

def main():
    random.seed(42)

    n_samples = 100
    n_features = 3

    X = []
    y = []

    for _ in range(n_samples):
        features = []
        for _ in range(n_features):
            features.append(random.uniform(-1, 1))
        X.append(features)

        z = 0.0
        for j in range(n_features):
            z += features[j] * (j + 1)
        prob = sigmoid(z)
        label = 1 if random.random() < prob else 0
        y.append(label)

    k_folds = 5

    probabilities = cross_validate_predict_proba(X, y, k=k_folds)

    print("First 5 probability predictions (negative_class_prob, positive_class_prob):")
    count = 0
    for prob_pair in probabilities:
        if count < 5:
            print(prob_pair)
            count += 1

    print("\nTotal number of predictions:", len(probabilities))

if __name__ == "__main__":
    main()

import math
import random

def sigmoid(z):
    if z >= 0:
        return 1.0 / (1.0 + math.exp(-z))
    else:
        exp_z = math.exp(z)
        return exp_z / (1.0 + exp_z)

def dot_product(v1, v2):
    result = 0.0
    for i in range(len(v1)):
        result += v1[i] * v2[i]
    return result

def add_bias_feature(x_row):
    new_row = [1.0]
    for val in x_row:
        new_row.append(val)
    return new_row

def prepare_data_with_bias(X, y):
    X_new = []
    for row in X:
        X_new.append(add_bias_feature(row))
    return X_new, y

def train_logistic_regression(X, y, learning_rate=0.1, iterations=1000):
    n_samples = len(X)
    n_features = len(X[0])

    weights = [0.0] * n_features

    for _ in range(iterations):
        gradients = [0.0] * n_features

        for i in range(n_samples):
            z = dot_product(X[i], weights)
            prediction = sigmoid(z)
            error = prediction - y[i]

            for j in range(n_features):
                gradients[j] += error * X[i][j]

        for j in range(n_features):
            weights[j] -= learning_rate * (gradients[j] / n_samples)

    return weights

def predict_proba_single(X, weights):
    probabilities = []
    for row in X:
        z = dot_product(row, weights)
        prob = sigmoid(z)
        probabilities.append(prob)
    return probabilities

def create_folds(data_X, data_y, n_folds):
    n_samples = len(data_X)
    fold_size = n_samples // n_folds
    folds_X = []
    folds_y = []

    for i in range(n_folds):
        start_idx = i * fold_size
        if i == n_folds - 1:
            end_idx = n_samples
        else:
            end_idx = (i + 1) * fold_size

        current_fold_X = []
        current_fold_y = []

        for j in range(start_idx, end_idx):
            current_fold_X.append(data_X[j])
            current_fold_y.append(data_y[j])

        folds_X.append(current_fold_X)
        folds_y.append(current_fold_y)

    return folds_X, folds_y

def cross_validate_logistic_regression(X, y, n_folds=5):
    X_bias, y = prepare_data_with_bias(X, y)
    folds_X, folds_y = create_folds(X_bias, y, n_folds)

    all_predictions = [0.0] * len(y)

    for i in range(n_folds):
        test_fold_X = folds_X[i]
        test_fold_y = folds_y[i]

        train_X = []
        train_y = []

        for j in range(n_folds):
            if j != i:
                for k in range(len(folds_X[j])):
                    train_X.append(folds_X[j][k])
                    train_y.append(folds_y[j][k])

        weights = train_logistic_regression(train_X, train_y)

        fold_predictions = predict_proba_single(test_fold_X, weights)

        start_idx = 0
        for j in range(n_folds):
            if j < i:
                start_idx += len(folds_y[j])

        for k in range(len(test_fold_y)):
            all_predictions[start_idx + k] = fold_predictions[k]

    return all_predictions

