import math

def manual_mean(values):
    total = 0.0
    count = 0
    for val in values:
        total = total + val
        count = count + 1
    if count == 0:
        return 0.0
    return total / float(count)

def manual_cross_val_score(model, X, y, cv):
    n_samples = len(X)
    fold_size = n_samples // cv

    scores = []

    for i in range(cv):
        start_idx = i * fold_size

        if i == cv - 1:
            end_idx = n_samples
        else:
            end_idx = (i + 1) * fold_size

        X_test = []
        y_test = []
        X_train = []
        y_train = []

        for j in range(n_samples):
            if start_idx <= j < end_idx:
                X_test.append(X[j])
                y_test.append(y[j])
            else:
                X_train.append(X[j])
                y_train.append(y[j])

        model.fit(X_train, y_train)
        predictions = model.predict(X_test)

        correct_count = 0
        for k in range(len(predictions)):
            if predictions[k] == y_test[k]:
                correct_count = correct_count + 1

        accuracy = float(correct_count) / float(len(predictions))
        scores.append(accuracy)

    return scores

def get_model_name(model):
    model_str = str(model)

    if '(' in model_str:
        name_part = model_str.split('(')[0]
        return name_part.strip()
    else:
        return model_str.strip()

class LinearRegression:
    def __init__(self, copy_X=True, fit_intercept=True, n_jobs=1, normalize=False):
        self.copy_X = copy_X
        self.fit_intercept = fit_intercept
        self.n_jobs = n_jobs
        self.normalize = normalize
        self.coef_ = None
        self.intercept_ = 0.0

    def fit(self, X, y):
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        sum_x = [0.0] * n_features
        sum_y = 0.0
        sum_xy = [0.0] * n_features
        sum_xx = [0.0] * n_features

        for i in range(n_samples):
            y_val = y[i]
            sum_y = sum_y + y_val
            for j in range(n_features):
                x_val = X[i][j]
                sum_x[j] = sum_x[j] + x_val
                sum_xy[j] = sum_xy[j] + (x_val * y_val)
                sum_xx[j] = sum_xx[j] + (x_val * x_val)

        mean_x = [0.0] * n_features
        mean_y = 0.0

        if n_samples > 0:
            for j in range(n_features):
                mean_x[j] = sum_x[j] / float(n_samples)
            mean_y = sum_y / float(n_samples)

        self.coef_ = [0.0] * n_features
        for j in range(n_features):
            numerator = sum_xy[j] - (sum_x[j] * mean_y)
            denominator = sum_xx[j] - (sum_x[j] * mean_x[j])
            if denominator != 0:
                self.coef_[j] = numerator / denominator
            else:
                self.coef_[j] = 0.0

        self.intercept_ = mean_y
        for j in range(n_features):
            self.intercept_ = self.intercept_ - (self.coef_[j] * mean_x[j])

    def predict(self, X):
        predictions = []
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        for i in range(n_samples):
            pred_val = self.intercept_
            for j in range(n_features):
                pred_val = pred_val + (self.coef_[j] * X[i][j])
            predictions.append(pred_val)

        return predictions

class LogisticRegression:
    def __init__(self, penalty='l2', C=1.0, solver='lbfgs', max_iter=100):
        self.penalty = penalty
        self.C = C
        self.solver = solver
        self.max_iter = max_iter
        self.coef_ = None
        self.intercept_ = 0.0

    def _sigmoid(self, z):
        if z > 500:
            return 1.0
        if z < -500:
            return 0.0
        return 1.0 / (1.0 + math.exp(-z))

    def fit(self, X, y):
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        self.coef_ = [0.0] * n_features
        self.intercept_ = 0.0

        learning_rate = 0.1

        for iteration in range(self.max_iter):
            grad_coef = [0.0] * n_features
            grad_intercept = 0.0

            for i in range(n_samples):
                z = self.intercept_
                for j in range(n_features):
                    z = z + (self.coef_[j] * X[i][j])

                pred = self._sigmoid(z)
                error = pred - y[i]

                grad_intercept = grad_intercept + error
                for j in range(n_features):
                    grad_coef[j] = grad_coef[j] + (error * X[i][j])

            for j in range(n_features):
                self.coef_[j] = self.coef_[j] - (learning_rate * grad_coef[j] / float(n_samples))
            self.intercept_ = self.intercept_ - (learning_rate * grad_intercept / float(n_samples))

    def predict(self, X):
        predictions = []
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        for i in range(n_samples):
            z = self.intercept_
            for j in range(n_features):
                z = z + (self.coef_[j] * X[i][j])

            pred_prob = self._sigmoid(z)
            if pred_prob >= 0.5:
                predictions.append(1)
            else:
                predictions.append(0)

        return predictions

class DecisionTreeClassifier:
    def __init__(self, criterion='gini', max_depth=None):
        self.criterion = criterion
        self.max_depth = max_depth
        self.tree = None

    def _gini(self, y_list):
        if len(y_list) == 0:
            return 0.0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        p0 = float(count_0) / float(len(y_list))
        p1 = float(count_1) / float(len(y_list))

        return 1.0 - (p0 * p0) - (p1 * p1)

    def _entropy(self, y_list):
        if len(y_list) == 0:
            return 0.0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        p0 = float(count_0) / float(len(y_list))
        p1 = float(count_1) / float(len(y_list))

        if p0 == 0.0 and p1 == 0.0:
            return 0.0

        result = 0.0
        if p0 > 0.0:
            result = result - (p0 * math.log2(p0))
        if p1 > 0.0:
            result = result - (p1 * math.log2(p1))

        return result

    def _information_gain(self, y_parent, y_left, y_right):
        impurity_func = self._gini if self.criterion == 'gini' else self._entropy

        parent_impurity = impurity_func(y_parent)

        n_total = len(y_parent)
        n_left = len(y_left)
        n_right = len(y_right)

        if n_total == 0:
            return 0.0

        left_weight = float(n_left) / float(n_total)
        right_weight = float(n_right) / float(n_total)

        child_impurity = (left_weight * impurity_func(y_left)) + (right_weight * impurity_func(y_right))

        return parent_impurity - child_impurity

    def _build_tree(self, X, y, depth):
        if self.max_depth is not None and depth >= self.max_depth:
            return {'leaf': True, 'value': self._majority_vote(y)}

        if len(set(y)) == 1 or len(y) <= 1:
            return {'leaf': True, 'value': self._majority_vote(y)}

        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        best_gain = -1.0
        best_feature = -1
        best_threshold = 0.0

        for feature_idx in range(n_features):
            values = []
            for i in range(n_samples):
                values.append(X[i][feature_idx])

            min_val = values[0]
            max_val = values[0]
            for val in values:
                if val < min_val:
                    min_val = val
                if val > max_val:
                    max_val = val

            step = (max_val - min_val) / 10.0 if max_val != min_val else 1.0

            for threshold in range(int(min_val), int(max_val) + 1):
                y_left = []
                y_right = []

                for i in range(n_samples):
                    if X[i][feature_idx] <= threshold:
                        y_left.append(y[i])
                    else:
                        y_right.append(y[i])

                if len(y_left) == 0 or len(y_right) == 0:
                    continue

                gain = self._information_gain(y, y_left, y_right)

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = float(threshold)

        if best_feature == -1:
            return {'leaf': True, 'value': self._majority_vote(y)}

        X_left = []
        y_left = []
        X_right = []
        y_right = []

        for i in range(n_samples):
            if X[i][best_feature] <= best_threshold:
                X_left.append(X[i])
                y_left.append(y[i])
            else:
                X_right.append(X[i])
                y_right.append(y[i])

        left_tree = self._build_tree(X_left, y_left, depth + 1)
        right_tree = self._build_tree(X_right, y_right, depth + 1)

        return {
            'leaf': False,
            'feature': best_feature,
            'threshold': best_threshold,
            'left': left_tree,
            'right': right_tree
        }

    def _majority_vote(self, y_list):
        if len(y_list) == 0:
            return 0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        return 1 if count_1 > count_0 else 0

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, 0)

    def _predict_single(self, x, node):
        if node['leaf']:
            return node['value']

        if x[node['feature']] <= node['threshold']:
            return self._predict_single(x, node['left'])
        else:
            return self._predict_single(x, node['right'])

    def predict(self, X):
        predictions = []
        for i in range(len(X)):
            pred = self._predict_single(X[i], self.tree)
            predictions.append(pred)
        return predictions

def main():
    X = [
        [1.0, 2.0], [2.0, 3.0], [3.0, 4.0], [4.0, 5.0], [5.0, 6.0],
        [1.5, 2.5], [2.5, 3.5], [3.5, 4.5], [4.5, 5.5], [5.5, 6.5]
    ]

    y = [0, 0, 0, 1, 1, 0, 0, 1, 1, 1]

    models = [
        LinearRegression(),
        LogisticRegression(),
        DecisionTreeClassifier()
    ]

    cv_folds = 3

    for model in models:
        scores = manual_cross_val_score(model, X, y, cv_folds)
        mean_score = manual_mean(scores)
        model_name = get_model_name(model)

        print("Name Model: " + model_name + ", Mean Score: " + str(mean_score))

if __name__ == "__main__":
    main()

import sys
import re
import math
from collections import defaultdict

# Manual implementation of TfidfVectorizer without sklearn or numpy
class ManualTfidfVectorizer:
    def __init__(self, lowercase=True):
        self.lowercase = lowercase
        self.vocabulary_ = {}
        self.idf_ = {}
        self.feature_names_ = []

    def _tokenize(self, text):
        if self.lowercase:
            text = text.lower()
        # Simple tokenization: split by non-alphanumeric characters
        tokens = re.findall(r'\b\w+\b', text)
        return tokens

    def fit(self, documents):
        doc_count = len(documents)
        term_doc_freq = defaultdict(int)

        # Count document frequency for each term
        for doc in documents:
            tokens = self._tokenize(doc)
            unique_tokens = set(tokens)
            for token in unique_tokens:
                term_doc_freq[token] += 1

        # Build vocabulary and IDF
        sorted_terms = []
        for term in term_doc_freq:
            sorted_terms.append(term)

        # Manual sorting (bubble sort) to ensure deterministic order
        n = len(sorted_terms)
        for i in range(n):
            for j in range(0, n - i - 1):
                if sorted_terms[j] > sorted_terms[j + 1]:
                    temp = sorted_terms[j]
                    sorted_terms[j] = sorted_terms[j + 1]
                    sorted_terms[j + 1] = temp

        self.vocabulary_ = {}
        for idx, term in enumerate(sorted_terms):
            self.vocabulary_[term] = idx
            # IDF calculation: log(N / (df + 1)) + 1 (smoothed)
            df = term_doc_freq[term]
            idf_val = math.log(doc_count / (df + 1)) + 1.0
            self.idf_[term] = idf_val

        self.feature_names_ = sorted_terms
        return self

    def transform(self, documents):
        # Initialize result matrix manually
        n_docs = len(documents)
        n_features = len(self.vocabulary_)

        # Create a list of lists for the matrix
        matrix = []
        for _ in range(n_docs):
            row = [0.0] * n_features
            matrix.append(row)

        for doc_idx, doc in enumerate(documents):
            tokens = self._tokenize(doc)

            # Count term frequencies in this document
            tf_counts = defaultdict(int)
            for token in tokens:
                if token in self.vocabulary_:
                    tf_counts[token] += 1

            # Calculate TF-IDF scores
            doc_norm = 0.0
            temp_row = [0.0] * n_features

            for term, count in tf_counts.items():
                idx = self.vocabulary_[term]
                tf_val = count / len(tokens) if len(tokens) > 0 else 0.0
                idf_val = self.idf_.get(term, 0.0)
                score = tf_val * idf_val
                temp_row[idx] = score
                doc_norm += score ** 2

            # L2 normalization
            if doc_norm > 0:
                norm_factor = math.sqrt(doc_norm)
                for i in range(n_features):
                    matrix[doc_idx][i] = temp_row[i] / norm_factor
            else:
                matrix[doc_idx] = temp_row

        return matrix

    def fit_transform(self, documents):
        self.fit(documents)
        return self.transform(documents)

# Manual implementation of NMF (Non-negative Matrix Factorization) using multiplicative update rules
class ManualNMF:
    def __init__(self, n_components=2, max_iter=100, tol=1e-4):
        self.n_components = n_components
        self.max_iter = max_iter
        self.tol = tol

    def _initialize(self, V, n_samples, n_features):
        # Initialize W and H with small random values (using deterministic pseudo-random)
        # Using simple counter-based initialization for reproducibility without numpy
        import random
        random.seed(42)

        W = []
        for i in range(n_samples):
            row = [random.random() * 0.1 + 0.01 for _ in range(self.n_components)]
            W.append(row)

        H = []
        for j in range(self.n_components):
            row = [random.random() * 0.1 + 0.01 for _ in range(n_features)]
            H.append(row)

        return W, H

    def _matrix_multiply(self, A, B):
        # Multiply matrix A (m x k) and B (k x n) -> result (m x n)
        m = len(A)
        k = len(A[0]) if m > 0 else 0
        n = len(B[0]) if len(B) > 0 else 0

        result = []
        for i in range(m):
            row = [0.0] * n
            for j in range(n):
                val = 0.0
                for l in range(k):
                    val += A[i][l] * B[l][j]
                row[j] = val
            result.append(row)
        return result

    def _matrix_transpose(self, A):
        m = len(A)
        n = len(A[0]) if m > 0 else 0
        result = []
        for j in range(n):
            row = [A[i][j] for i in range(m)]
            result.append(row)
        return result

    def _reconstruct_error(self, V, W, H):
        # Calculate Frobenius norm of (V - WH)
        WH = self._matrix_multiply(W, H)
        error_sum = 0.0

        for i in range(len(V)):
            for j in range(len(V[0])):
                diff = V[i][j] - WH[i][j]
                error_sum += diff * diff

        return math.sqrt(error_sum)

    def fit(self, V):
        n_samples = len(V)
        n_features = len(V[0]) if n_samples > 0 else 0

        W, H = self._initialize(V, n_samples, n_features)

        prev_error = float('inf')

        for iteration in range(self.max_iter):
            # Update H: H = H * (W^T V) / (W^T W H + epsilon)
            W_T = self._matrix_transpose(W)
            W_T_V = self._matrix_multiply(W_T, V)
            W_T_W = self._matrix_multiply(W_T, W)
            W_T_W_H = self._matrix_multiply(W_T_W, H)

            for j in range(self.n_components):
                for k in range(n_features):
                    numerator = W_T_V[j][k]
                    denominator = W_T_W_H[j][k] + 1e-10
                    H[j][k] = H[j][k] * (numerator / denominator)

            # Update W: W = W * (V H^T) / (W H H^T + epsilon)
            H_T = self._matrix_transpose(H)
            V_H_T = self._matrix_multiply(V, H_T)
            H_H_T = self._matrix_multiply(H, H_T)
            W_H_H_T = self._matrix_multiply(W, H_H_T)

            for i in range(n_samples):
                for j in range(self.n_components):
                    numerator = V_H_T[i][j]
                    denominator = W_H_H_T[i][j] + 1e-10
                    W[i][j] = W[i][j] * (numerator / denominator)

            # Check convergence
            current_error = self._reconstruct_error(V, W, H)
            if abs(prev_error - current_error) < self.tol:
                break
            prev_error = current_error

        self.W_ = W
        self.H_ = H
        return self

    def transform(self, V):
        # For NMF, transform usually returns the W matrix (latent features)
        return self.W_

    def fit_transform(self, V):
        self.fit(V)
        return self.transform(V)

# Manual Pipeline implementation
class ManualPipeline:
    def __init__(self, steps):
        self.steps = steps
        self.named_steps = {}
        for name, transformer in steps:
            self.named_steps[name] = transformer

    def fit_transform(self, X):
        current_data = X

        # Store intermediate results
        intermediate_results = {}

        for name, transformer in self.steps:
            if hasattr(transformer, 'fit_transform'):
                current_data = transformer.fit_transform(current_data)
            elif hasattr(transformer, 'fit') and hasattr(transformer, 'transform'):
                transformer.fit(current_data)
                current_data = transformer.transform(current_data)

            intermediate_results[name] = current_data

        self.intermediate_results_ = intermediate_results
        return current_data

    def get_intermediate_result(self, step_name):
        if not hasattr(self, 'intermediate_results_'):
            raise ValueError("Pipeline has not been fitted yet.")

        if step_name not in self.intermediate_results_:
            raise ValueError(f"Step '{step_name}' not found in pipeline or no intermediate result available.")

        return self.intermediate_results_[step_name]

# Main execution code
def main():
    # Sample data
    data = [
        "Salut comment tu vas",
        "Hey how are you today",
        "I am okay and you ?"
    ]

    # Create pipeline with manual implementations
    pipe = ManualPipeline([
        ("tf_idf", ManualTfidfVectorizer()),
        ("nmf", ManualNMF(n_components=2))
    ])

    # Fit and transform
    final_result = pipe.fit_transform(data)

    # Get intermediate result (TF-IDF output)
    tfidf_output = pipe.get_intermediate_result("tf_idf")

    print("Intermediate TF-IDF Output:")
    for i, row in enumerate(tfidf_output):
        print(f"Document {i}: {row}")

    print("\nFinal NMF Result (W matrix):")
    for i, row in enumerate(final_result):
        print(f"Document {i}: {row}")

if __name__ == "__main__":
    main()

import math
import random

class DecisionTreeRegressor:
    def __init__(self, max_depth=None, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.tree = None

    def fit(self, X, y):
        # Ensure X is a list of lists (samples x features)
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        self.tree = self._build_tree(X, y, 0)

    def _build_tree(self, X, y, depth):
        n_samples = len(y)

        # Stopping conditions
        if (self.max_depth is not None and depth >= self.max_depth) or \
           n_samples < self.min_samples_split or \
           n_samples == 0:
            return self._calculate_mean(y)

        # Find best split
        best_feature, best_threshold, best_gain = self._find_best_split(X, y)

        if best_gain <= 0:
            return self._calculate_mean(y)

        # Split data
        left_indices = []
        right_indices = []

        for i in range(n_samples):
            if X[i][best_feature] <= best_threshold:
                left_indices.append(i)
            else:
                right_indices.append(i)

        if len(left_indices) == 0 or len(right_indices) == 0:
            return self._calculate_mean(y)

        # Create left and right subsets
        X_left = [X[i] for i in left_indices]
        y_left = [y[i] for i in left_indices]
        X_right = [X[i] for i in right_indices]
        y_right = [y[i] for i in right_indices]

        # Recursively build subtrees
        return {
            'feature': best_feature,
            'threshold': best_threshold,
            'left': self._build_tree(X_left, y_left, depth + 1),
            'right': self._build_tree(X_right, y_right, depth + 1)
        }

    def _find_best_split(self, X, y):
        n_samples = len(y)
        n_features = len(X[0])
        best_gain = -float('inf')
        best_feature = None
        best_threshold = None

        # Calculate total variance (MSE) before split
        mean_y = self._calculate_mean(y)
        total_var = 0.0
        for val in y:
            total_var += (val - mean_y) ** 2

        for feature_idx in range(n_features):
            # Get unique values for this feature to use as potential thresholds
            feature_values = [X[i][feature_idx] for i in range(n_samples)]

            # Sort manually without using sorted()
            sorted_indices = list(range(n_samples))
            for i in range(len(sorted_indices)):
                for j in range(i + 1, len(sorted_indices)):
                    if feature_values[sorted_indices[i]] > feature_values[sorted_indices[j]]:
                        temp = sorted_indices[i]
                        sorted_indices[i] = sorted_indices[j]
                        sorted_indices[j] = temp

            # Try splitting between consecutive unique values
            for i in range(len(sorted_indices) - 1):
                idx1 = sorted_indices[i]
                idx2 = sorted_indices[i + 1]

                if feature_values[idx1] == feature_values[idx2]:
                    continue

                threshold = (feature_values[idx1] + feature_values[idx2]) / 2.0

                # Split data based on this threshold
                left_y = []
                right_y = []

                for k in range(n_samples):
                    if X[k][feature_idx] <= threshold:
                        left_y.append(y[k])
                    else:
                        right_y.append(y[k])

                if len(left_y) == 0 or len(right_y) == 0:
                    continue

                # Calculate variance reduction (gain)
                mean_left = self._calculate_mean(left_y)
                mean_right = self._calculate_mean(right_y)

                var_left = 0.0
                for val in left_y:
                    var_left += (val - mean_left) ** 2

                var_right = 0.0
                for val in right_y:
                    var_right += (val - mean_right) ** 2

                # Weighted variance after split
                weighted_var = (len(left_y) * var_left + len(right_y) * var_right) / n_samples

                gain = total_var - weighted_var

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    def _calculate_mean(self, y):
        if len(y) == 0:
            return 0.0

        total = 0.0
        for val in y:
            total += val

        return total / len(y)

    def predict(self, X):
        # Ensure X is a list of lists
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        predictions = []
        for sample in X:
            pred = self._predict_single(sample, self.tree)
            predictions.append(pred)

        return predictions

    def _predict_single(self, sample, node):
        if isinstance(node, (int, float)):
            return node

        if sample[node['feature']] <= node['threshold']:
            return self._predict_single(sample, node['left'])
        else:
            return self._predict_single(sample, node['right'])


class RandomForestRegressor:
    def __init__(self, n_estimators=100, max_depth=None, min_samples_split=2, random_state=None):
        self.n_estimators = n_estimators
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.random_state = random_state
        self.trees = []

    def fit(self, X, y):
        # Ensure X is a list of lists (samples x features)
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        n_samples = len(y)

        if self.random_state is not None:
            random.seed(self.random_state)

        self.trees = []

        for _ in range(self.n_estimators):
            # Bootstrap sampling (random sampling with replacement)
            indices = []
            for _ in range(n_samples):
                idx = random.randint(0, n_samples - 1)
                indices.append(idx)

            X_bootstrap = [X[i] for i in indices]
            y_bootstrap = [y[i] for i in indices]

            # Train a decision tree on bootstrap sample
            tree = DecisionTreeRegressor(
                max_depth=self.max_depth,
                min_samples_split=self.min_samples_split
            )
            tree.fit(X_bootstrap, y_bootstrap)
            self.trees.append(tree)

    def predict(self, X):
        # Ensure X is a list of lists
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        all_predictions = []

        # Get predictions from each tree
        for tree in self.trees:
            tree_preds = tree.predict(X)
            all_predictions.append(tree_preds)

        # Average predictions across all trees
        n_samples = len(X)
        final_predictions = []

        for i in range(n_samples):
            total = 0.0
            for tree_idx in range(len(self.trees)):
                total += all_predictions[tree_idx][i]

            avg = total / len(self.trees)
            final_predictions.append(avg)

        return final_predictions


