import re

class Tokenizer:
    def __init__(self):
        self.tokens = []

    def tokenize(self, text):
        # Manual tokenization using regex split on non-alphanumeric characters
        # No list comprehensions or built-in split methods that return lists directly used in a comprehension
        result = []
        pattern = r'[^a-zA-Z0-9]+'
        parts = re.split(pattern, text)

        for part in parts:
            if len(part) > 0:
                result.append(part)

        return result

class TfidfVectorizer:
    def __init__(self, preprocessor=None):
        self.preprocessor = preprocessor
        self.tokenizer = Tokenizer()
        self.vocabulary_ = {}
        self.idf_ = {}
        self.documents_ = []

    def fit(self, documents):
        # Process documents and build vocabulary
        processed_docs = []

        for doc in documents:
            if self.preprocessor is not None:
                doc = self.preprocessor(doc)

            tokens = self.tokenizer.tokenize(doc)
            processed_docs.append(tokens)

            for token in tokens:
                if token not in self.vocabulary_:
                    vocab_id = len(self.vocabulary_)
                    self.vocabulary_[token] = vocab_id

        # Calculate IDF manually
        num_docs = 0
        for doc in documents:
            num_docs += 1

        # Count document frequency for each term
        df_counts = {}
        for tokens in processed_docs:
            unique_tokens = []
            seen = []
            for token in tokens:
                is_seen = False
                for s in seen:
                    if s == token:
                        is_seen = True
                        break
                if not is_seen:
                    seen.append(token)
                    unique_tokens.append(token)

            for token in unique_tokens:
                if token in df_counts:
                    df_counts[token] += 1
                else:
                    df_counts[token] = 1

        # Calculate IDF values
        import math
        for term, count in self.vocabulary_.items():
            doc_freq = df_counts.get(term, 0)
            if doc_freq > 0:
                idf_val = math.log((num_docs + 1) / (doc_freq + 1)) + 1
            else:
                idf_val = 0
            self.idf_[term] = idf_val

        self.documents_ = processed_docs
        return self

    def transform(self, documents):
        # Transform documents to TF-IDF matrix representation
        result = []

        for doc in documents:
            if self.preprocessor is not None:
                doc = self.preprocessor(doc)

            tokens = self.tokenizer.tokenize(doc)

            # Calculate term frequencies
            tf_counts = {}
            total_terms = 0

            for token in tokens:
                if token in tf_counts:
                    tf_counts[token] += 1
                else:
                    tf_counts[token] = 1
                total_terms += 1

            # Build TF-IDF vector for this document
            doc_vector = {}

            for term, count in self.vocabulary_.items():
                if term in tf_counts:
                    tf_val = tf_counts[term] / total_terms if total_terms > 0 else 0
                    idf_val = self.idf_[term]
                    tfidf_val = tf_val * idf_val
                    doc_vector[count] = tfidf_val

            result.append(doc_vector)

        return result

    def fit_transform(self, documents):
        self.fit(documents)
        return self.transform(documents)

def prePro(text):
    # Custom preprocessor to convert uppercase to lowercase
    result = ""
    for char in text:
        if 'A' <= char <= 'Z':
            # Convert uppercase to lowercase manually
            offset = ord('a') - ord('A')
            new_char = chr(ord(char) + offset)
            result += new_char
        else:
            result += char
    return result

# Example usage
if __name__ == "__main__":
    documents = [
        "Hello World",
        "HELLO world",
        "Python Programming",
        "PYTHON programming"
    ]

    # Create vectorizer with custom preprocessor
    vectorizer = TfidfVectorizer(preprocessor=prePro)

    # Fit and transform
    tfidf_matrix = vectorizer.fit_transform(documents)

    # Print results
    print("Vocabulary:", vectorizer.vocabulary_)
    print("\nTF-IDF Matrix:")
    for i, doc_vector in enumerate(tfidf_matrix):
        print(f"Document {i}:")
        for term_id, value in doc_vector.items():
            term = None
            for t, tid in vectorizer.vocabulary_.items():
                if tid == term_id:
                    term = t
                    break
            print(f"  '{term}': {value:.4f}")

