import re

def custom_tokenizer(text):
    tokens = []
    current_token = ""

    i = 0
    while i < len(text):
        char = text[i]

        if char.isalnum():
            current_token += char
        elif char in ['!', '?', '"', "'"]:
            if current_token:
                tokens.append(current_token)
                current_token = ""
            tokens.append(char)
        else:
            if current_token:
                tokens.append(current_token)
                current_token = ""

        i += 1

    if current_token:
        tokens.append(current_token)

    return tokens

def count_vectorizer_manual(texts, vocabulary=None):
    all_tokens = []

    for text in texts:
        tokens = custom_tokenizer(text)
        all_tokens.extend(tokens)

    unique_words = []
    for token in all_tokens:
        is_new = True
        for existing in unique_words:
            if existing == token:
                is_new = False
                break
        if is_new:
            unique_words.append(token)

    word_to_index = {}
    index = 0
    for word in unique_words:
        word_to_index[word] = index
        index += 1

    matrix = []
    for text in texts:
        tokens = custom_tokenizer(text)
        row = []
        count = 0
        while count < len(unique_words):
            row.append(0)
            count += 1

        for token in tokens:
            if token in word_to_index:
                idx = word_to_index[token]
                row[idx] = row[idx] + 1

        matrix.append(row)

    return matrix, unique_words

