            for val in unique_vals:
                mapping[val] = float(idx)
                rev_mapping[float(idx)] = val
                idx += 1

            self.unique_values_map[i] = mapping
            self.reverse_map[i] = rev_mapping

        # Transform X
        for row in X:
            encoded_row = []
            for i in range(n_features):
                encoded_row.append(self.unique_values_map[i][row[i]])
            encoded_X.append(encoded_row)

        # Encode target
        unique_targets = []
        for val in y:
            is_new = True
            for u in unique_vals:
                if u == val:
                    is_new = False
                    break
            if is_new:
                unique_targets.append(val)

        target_mapping = {}
        idx = 0
        for val in unique_targets:
            target_mapping[val] = float(idx)
            idx += 1

        encoded_y = []
        for val in y:
            encoded_y.append(target_mapping[val])

        self.target_unique_values = unique_targets

        return encoded_X, encoded_y

    def _gini(self, labels):
        if len(labels) == 0:
            return 0.0

        counts = {}
        for label in labels:
            if label in counts:
                counts[label] += 1
            else:
                counts[label] = 1

        total = float(len(labels))
        impurity = 1.0
        for count in counts.values():
            prob = count / total
            impurity -= (prob * prob)

        return impurity

    def _information_gain(self, parent_labels, left_labels, right_labels):
        if len(parent_labels) == 0:
            return 0.0

        n = float(len(parent_labels))
        n_left = float(len(left_labels))
        n_right = float(len(right_labels))

        if n_left == 0 or n_right == 0:
            return 0.0

        parent_gini = self._gini(parent_labels)
        left_gini = self._gini(left_labels)
        right_gini = self._gini(right_labels)

        weighted_child_gini = (n_left / n) * left_gini + (n_right / n) * right_gini

        return parent_gini - weighted_child_gini

    def _find_best_split(self, X, y):
        best_gain = -1.0
        best_feature = -1
        best_threshold = None

        n_samples = len(X)
        if n_samples == 0:
            return None, None, None

        n_features = len(X[0])

        for feature_idx in range(n_features):
            # Get unique values for this feature to use as thresholds
            feature_values = []
            for row in X:
                feature_values.append(row[feature_idx])

            unique_vals = []
            for val in feature_values:
                is_new = True
                for u in unique_vals:
                    if u == val:
                        is_new = False
                        break
                if is_new:
                    unique_vals.append(val)

            # Sort unique values manually (bubble sort)
            len_unique = len(unique_vals)
            for i in range(len_unique):
                for j in range(i + 1, len_unique):
                    if unique_vals[i] > unique_vals[j]:
                        temp = unique_vals[i]
                        unique_vals[i] = unique_vals[j]
                        unique_vals[j] = temp

            # Try thresholds between unique values
            for i in range(len_unique - 1):
                threshold = (unique_vals[i] + unique_vals[i+1]) / 2.0

                left_labels = []
                right_labels = []

                for k in range(n_samples):
                    if X[k][feature_idx] <= threshold:
                        left_labels.append(y[k])
                    else:
                        right_labels.append(y[k])

                gain = self._information_gain(y, left_labels, right_labels)

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    def _build_tree(self, X, y, depth):
        # Check stopping conditions
        if self.max_depth is not None and depth >= self.max_depth:
            return self._create_leaf(y)

        # Check if all labels are the same
        first_label = y[0]
        all_same = True
        for label in y:
            if label != first_label:
                all_same = False
                break

        if all_same or len(y) == 0:
            return self._create_leaf(y)

        # Find best split
        feature_idx, threshold, gain = self._find_best_split(X, y)

        if feature_idx is None or gain <= 0.0:
            return self._create_leaf(y)

        # Split data
        left_X = []
        right_X = []
        left_y = []
        right_y = []

        for i in range(len(X)):
            if X[i][feature_idx] <= threshold:
                left_X.append(X[i])
                left_y.append(y[i])
            else:
                right_X.append(X[i])
                right_y.append(y[i])

        # Recursively build subtrees
        left_subtree = self._build_tree(left_X, left_y, depth + 1)
        right_subtree = self._build_tree(right_X, right_y, depth + 1)

        return {
            'feature': feature_idx,
            'threshold': threshold,
            'left': left_subtree,
            'right': right_subtree
        }

    def _create_leaf(self, y):
        if len(y) == 0:
            return {'leaf': True, 'value': None}

        # Count votes
        counts = {}
        for label in y:
            if label in counts:
                counts[label] += 1
            else:
                counts[label] = 1

        # Find majority class manually
        max_count = -1
        majority_label = None
        for label, count in counts.items():
            if count > max_count:
                max_count = count
                majority_label = label

        return {'leaf': True, 'value': majority_label}

    def fit(self, X, y):
        # Store original feature names if needed (not strictly necessary for logic)
        self.feature_names = list(range(len(X[0]))) if len(X) > 0 else []

        # Encode data
        encoded_X, encoded_y = self._encode_data(X, y)

        # Build tree
        self.tree = self._build_tree(encoded_X, encoded_y, 0)

        return self

    def _predict_single(self, x):
        # Encode single sample
        encoded_x = []
        for i in range(len(x)):
            if i in self.unique_values_map:
                encoded_x.append(self.unique_values_map[i][x[i]])
            else:
                encoded_x.append(0.0)

        node = self.tree

        while not node['leaf']:
            feature_idx = node['feature']
            threshold = node['threshold']

            if encoded_x[feature_idx] <= threshold:
                node = node['left']
            else:
                node = node['right']

        return node['value']

    def predict(self, X):
        predictions = []
        for row in X:
            pred_encoded = self._predict_single(row)

            # Map back to original string value
            if pred_encoded is not None and len(self.target_unique_values) > 0:
                # Find the index of pred_encoded in target_unique_values
                idx = 0
                found = False
                for val in self.target_unique_values:
                    if float(idx) == pred_encoded:
                        predictions.append(val)
                        found = True
                        break
                    idx += 1

                if not found:
                    # Fallback if mapping fails
                    predictions.append(self.target_unique_values[0])
            else:
                predictions.append(None)

        return predictions

    def score(self, X, y):
        predictions = self.predict(X)
        correct = 0
        for i in range(len(y)):
            if predictions[i] == y[i]:
                correct += 1

        if len(y) == 0:
            return 0.0

        return float(correct) / float(len(y))


# Example usage with string data
if __name__ == "__main__":
    # Sample data
    X = [['dsa', '2'], ['sato', '3'], ['dsa', '3'], ['sato', '2']]
    y = ['4', '5', '5', '4']

    clf = DecisionTreeClassifier()
    clf.fit(X, y)

    # Predict on training data
    predictions = clf.predict(X)

    print("Predictions:", predictions)
    print("Actual:", y)
    print("Score:", clf.score(X, y))

