import math

def tokenize(text):
    tokens = []
    current_token = ""
    for char in text:
        if char.isalnum():
            current_token += char.lower()
        else:
            if current_token:
                tokens.append(current_token)
                current_token = ""
    if current_token:
        tokens.append(current_token)
    return tokens

def build_vocabulary(documents):
    vocab = []
    for doc in documents:
        tokens = tokenize(doc)
        for token in tokens:
            is_new = True
            for existing in vocab:
                if existing == token:
                    is_new = False
                    break
            if is_new:
                vocab.append(token)
    return vocab

def compute_tf(tokens):
    tf_dict = {}
    total_tokens = 0
    for token in tokens:
        total_tokens += 1
        if token in tf_dict:
            tf_dict[token] += 1
        else:
            tf_dict[token] = 1

    # Normalize by document length
    normalized_tf = {}
    for token, count in tf_dict.items():
        normalized_tf[token] = count / total_tokens
    return normalized_tf

def compute_idf(documents, vocab):
    idf_dict = {}
    num_docs = len(documents)

    for term in vocab:
        doc_count = 0
        for doc in documents:
            tokens = tokenize(doc)
            if term in tokens:
                doc_count += 1

        # Avoid division by zero, though with valid data this shouldn't happen
        if doc_count == 0:
            idf_dict[term] = 0.0
        else:
            idf_dict[term] = math.log(num_docs / doc_count)

    return idf_dict

def compute_tfidf_vector(tokens, vocab, tf_dict, idf_dict):
    vector = []
    for term in vocab:
        tf_val = 0.0
        if term in tf_dict:
            tf_val = tf_dict[term]

        idf_val = 0.0
        if term in idf_dict:
            idf_val = idf_dict[term]

        vector.append(tf_val * idf_val)
    return vector

def compute_vector_magnitude(vector):
    sum_sq = 0.0
    for val in vector:
        sum_sq += val * val
    return math.sqrt(sum_sq)

def compute_dot_product(vec1, vec2):
    dot = 0.0
    # Ensure vectors are same length
    length = len(vec1)
    if len(vec2) < length:
        length = len(vec2)

    for i in range(length):
        dot += vec1[i] * vec2[i]
    return dot

def compute_cosine_similarity(vec1, vec2):
    mag1 = compute_vector_magnitude(vec1)
    mag2 = compute_vector_magnitude(vec2)

    if mag1 == 0.0 or mag2 == 0.0:
        return 0.0

    dot = compute_dot_product(vec1, vec2)
    return dot / (mag1 * mag2)

def main():
    # Input data
    items = ["1fgg", "2hhj", "3jkl"]
    descriptions = ["abcd ty", "abc r", "r df"]

    # 1. Tokenize each description
    tokenized_docs = []
    for desc in descriptions:
        tokenized_docs.append(tokenize(desc))

    # 2. Build vocabulary
    vocab = build_vocabulary(descriptions)

    # 3. Compute IDF
    idf_dict = compute_idf(descriptions, vocab)

    # 4. Compute TF-IDF vectors for each document
    tfidf_vectors = []
    for tokens in tokenized_docs:
        tf_dict = compute_tf(tokens)
        vector = compute_tfidf_vector(tokens, vocab, tf_dict, idf_dict)
        tfidf_vectors.append(vector)

    # 5. Calculate similarity matrix
    n_items = len(items)
    similarity_matrix = []

    for i in range(n_items):
        row = []
        for j in range(n_items):
            sim = compute_cosine_similarity(tfidf_vectors[i], tfidf_vectors[j])
            # Round to 1 decimal place for display consistency with example
            row.append(round(sim, 1))
        similarity_matrix.append(row)

    # Print the matrix header
    print("        ", end="")
    for item in items:
        print(f"{item:>8}", end="")
    print()

    # Print the matrix rows
    for i in range(n_items):
        print(f"{items[i]:>6}  ", end="")
        for j in range(n_items):
            print(f"{similarity_matrix[i][j]:>8.1f}", end="")
        print()

    # Example query: Similarity between "1fgg" and "2hhj"
    # Note: The user asked about "1ffg" in the text but "1fgg" in the data. 
    # Assuming they meant the first item "1fgg".
    target_item_1 = "1fgg"
    target_item_2 = "2hhj"

    idx1 = -1
    idx2 = -1

    for i in range(len(items)):
        if items[i] == target_item_1:
            idx1 = i
        if items[i] == target_item_2:
            idx2 = i

    if idx1 != -1 and idx2 != -1:
        sim_val = similarity_matrix[idx1][idx2]
        print(f"\nSimilarity between {target_item_1} and {target_item_2}: {sim_val}")
    else:
        print("\nOne or both items not found in the list.")

if __name__ == "__main__":
    main()

