data = {
    'ID': [1, 2, 3, 4, 5],
    'Field1': [1.15, 2, 1, 25, "and"]
}
df = pd.DataFrame(data)

# Initialize a list to store error values (non-integers)
error_values = []

# Iterate over the rows using iterrows()
for index, row in df.iterrows():
    value = row['Field1']

    # Check if the value is an integer type or can be converted to an integer without loss
    # We check: 
    # 1. If it's already an int (and not a bool, since bool is subclass of int)
    # 2. If it's a float that has no fractional part (e.g., 2.0)
    # 3. If it's a string that represents a whole number

    is_integer = False

    if isinstance(value, bool):
        continue # Skip booleans as they are technically ints but usually not desired here

    if isinstance(value, int):
        is_integer = True
    elif isinstance(value, float):
        # Check if it's a whole number (e.g., 2.0) and not infinity/nan
        import math
        if not math.isnan(value) and not math.isinf(value) and value == int(value):
            is_integer = True
    elif isinstance(value, str):
        try:
            # Try to convert string to float first to handle cases like "2.0" vs "2"
            f_val = float(value)
            if f_val == int(f_val):
                is_integer = True
        except ValueError:
            pass # Not a number

    if not is_integer:
        error_values.append(value)

