import pandas as pd
import numpy as np

# Create the DataFrame
data = {
    'a': [1, 1, 1, 2, 2, 2, 3, 3, 3],
    'b': [12, 13, 23, 22, 23, 24, 30, 35, 55]
}
df = pd.DataFrame(data)

# Group by column 'a' and apply softmax normalization to column 'b'
def softmax(x):
    e_x = np.exp(x - np.max(x))
    return e_x / e_x.sum()

df['softmax'] = df.groupby('a')['b'].transform(lambda x: softmax(x.values))

# Group by column 'a' and apply min-max normalization to column 'b'
def min_max_normalize(x):
    return (x - x.min()) / (x.max() - x.min())

df['min-max'] = df.groupby('a')['b'].transform(lambda x: min_max_normalize(x))

# Display the result
print(df)

