    if isinstance(x, list) and isinstance(y, list):
        if len(x) != len(y):
            return False
        return all(are_equal(a, b) for a, b in zip(x, y))

    if isinstance(x, tuple) and isinstance(y, tuple):
        if len(x) != len(y):
            return False
        return all(are_equal(a, b) for a, b in zip(x, y))

    # Fallback for other types (strings, etc.) - standard equality
    return x == y

