import csv

def read_csv_to_list(filename):
    data = []
    with open(filename, 'r', newline='') as file:
        reader = csv.reader(file)
        header = next(reader)
        for row in reader:
            data.append(row)
    return data, header

def get_type_at_index(data, index):
    if index < 0 or index >= len(data):
        return None
    return int(data[index][3])

def shuffle_data_by_indices(data, indices):
    shuffled = []
    for idx in indices:
        if idx < 0 or idx >= len(data):
            continue
        row = data[idx]
        shuffled.append(row)
    return shuffled

def count_type_changes(original_data, shuffled_data, original_header, shuffled_header):
    if len(original_data) != len(shuffled_data):
        return -1

    changes_count = 0
    changed_indices = []

    for i in range(len(original_data)):
        orig_row = original_data[i]
        shuf_row = shuffled_data[i]

        if orig_row[3] != shuf_row[3]:
            changes_count += 1
            changed_indices.append(i)

    return changes_count, changed_indices

def main():
    filename = 'data.csv'
    data, header = read_csv_to_list(filename)

    indices = [2, 4, 0, 3, 1, 5]
    shuffled_data = shuffle_data_by_indices(data, indices)

    changes_count, changed_indices = count_type_changes(data, shuffled_data, header, header)

    print("Number of rows with different Type:", changes_count)
    print("Indices of rows with different Type:", changed_indices)

if __name__ == "__main__":
    main()

