def parse_message(message_str):
    result = {}
    if not isinstance(message_str, str) or message_str.strip() == "":
        return result

    # Split by comma to get individual key-value pairs
    parts = message_str.split(", ")

    for part in parts:
        # Find the first colon to split key and value
        colon_index = part.find(":")
        if colon_index == -1:
            continue

        key = part[:colon_index].strip()
        value_part = part[colon_index + 1:].strip()

        # Handle empty values or values that are just whitespace
        if value_part == "":
            result[key] = "none"
        else:
            result[key] = value_part

    return result

def main():
    # Raw data as a list of dictionaries to simulate the input table
    raw_data = [
        {"name": "matt", "status": "active", "number": 12345, "message": "[job:  , money: none, wife: none]"},
        {"name": "james", "status": "active", "number": 23456, "message": "[group: band, wife: yes, money: 10000]"},
        {"name": "adam", "status": "inactive", "number": 34567, "message": "[job: none, money: none, wife:  , kids: one, group: jail]"}
    ]

    # Define the expected columns in the final output
    expected_columns = ["name", "status", "number", "job", "money", "wife", "group", "kids"]

    # Initialize the result list with empty dictionaries for each row
    result_rows = []

    for row in raw_data:
        new_row = {}

        # Copy static fields
        new_row["name"] = row["name"]
        new_row["status"] = row["status"]
        new_row["number"] = row["number"]

        # Parse the message field
        parsed_message = parse_message(row["message"])

        # Map parsed values to expected columns, defaulting to "none" if missing
        for col in ["job", "money", "wife", "group", "kids"]:
            if col in parsed_message:
                new_row[col] = parsed_message[col]
            else:
                new_row[col] = "none"

        result_rows.append(new_row)

    # Transpose the list of dictionaries into a list of lists for printing as a table
    # First, create a header row
    header_row = []
    for col in expected_columns:
        header_row.append(col)

    # Create data rows
    data_rows = []
    for row_dict in result_rows:
        current_data_row = []
        for col in expected_columns:
            current_data_row.append(row_dict[col])
        data_rows.append(current_data_row)

    # Print the table manually
    print("name\tstatus\tnumber\tjob\tmoney\twife\tgroup\tkids")
    for row in data_rows:
        print("\t".join(str(item) for item in row))

if __name__ == "__main__":
