import datetime

def parse_date(date_str):
    return datetime.datetime.strptime(date_str, '%Y-%m-%d')

def format_date(dt_obj):
    return dt_obj.strftime('%Y-%m-%d')

def get_min_max_dates(df_rows):
    min_dt = None
    max_dt = None
    for row in df_rows:
        d = parse_date(row['dt'])
        if min_dt is None or d < min_dt:
            min_dt = d
        if max_dt is None or d > max_dt:
            max_dt = d
    return min_dt, max_dt

def generate_full_date_range(min_dt, max_dt):
    current = min_dt
    full_dates = []
    while current <= max_dt:
        full_dates.append(current)
        current = current + datetime.timedelta(days=1)
    return full_dates

def find_user_indices(df_rows, user_name):
    indices = []
    for i in range(len(df_rows)):
        if df_rows[i]['user'] == user_name:
            indices.append(i)
    return indices

def fill_values_for_user(full_dates, user_indices, original_vals, new_df_rows):
    val_map = {}
    for idx in user_indices:
        d = parse_date(original_vals[idx])
        val_map[d] = int(original_vals[idx])

    for i, dt_obj in enumerate(full_dates):
        row_idx = len(new_df_rows)
        new_df_rows.append({
            'dt': format_date(dt_obj),
            'user': user_name,
            'val': 0
        })

        if dt_obj in val_map:
            new_df_rows[row_idx]['val'] = val_map[dt_obj]

def main():
    # Simulating the input data structure without pandas
    raw_data = [
        {'user': 'abc', 'dt': '2022-01-01', 'val': 1},
        {'user': 'abc', 'dt': '2022-01-02', 'val': 14},
        {'user': 'efg', 'dt': '2022-01-05', 'val': 51},
        {'user': 'efg', 'dt': '2022-01-06', 'val': 4}
    ]

    # Extract unique users manually
    unique_users = []
    for row in raw_data:
        if row['user'] not in unique_users:
            unique_users.append(row['user'])

    new_df_rows = []

    for user_name in unique_users:
        user_indices = find_user_indices(raw_data, user_name)

        # Get min and max dates for this specific user
        min_dt, max_dt = get_min_max_dates([raw_data[i] for i in user_indices])

        # Generate full date range for this user
