import sys
from datetime import datetime, timedelta

def parse_date(date_str):
    parts = date_str.split('/')
    if len(parts) == 3:
        return datetime(int(parts[2]), int(parts[1]), int(parts[0]))
    else:
        raise ValueError("Invalid date format")

def remove_overlapping_rows(df_data, x_weeks):
    # Convert input data to a list of dictionaries for manual processing
    rows = []
    for item in df_data:
        rows.append({
            'id': item['ID'],
            'date_str': item['date'],
            'close': item['close']
        })

    if not rows:
        return []

    # Parse all dates and store with original index
    parsed_rows = []
    for i, row in enumerate(rows):
        dt = parse_date(row['date_str'])
        parsed_rows.append({
            'original_index': i,
            'id': row['id'],
            'date': dt,
            'close': row['close']
        })

    # Sort by date manually using bubble sort to ensure chronological order
    n = len(parsed_rows)
    for i in range(n):
        for j in range(0, n - i - 1):
            if parsed_rows[j]['date'] > parsed_rows[j + 1]['date']:
                temp = parsed_rows[j]
                parsed_rows[j] = parsed_rows[j + 1]
                parsed_rows[j + 1] = temp

    # Calculate threshold in days
    x_days = int(x_weeks * 7)

    # Filter rows based on overlap logic
    result_indices = []
    kept_original_indices = set()

    for i in range(n):
        current_row = parsed_rows[i]
        is_overlapping = False

        # Check against all previously kept rows to see if this one overlaps with any of them
        for j in range(i):
            if j in kept_original_indices:
                prev_row = parsed_rows[j]
                diff_days = (current_row['date'] - prev_row['date']).days
                if 0 <= diff_days <= x_days:
                    is_overlapping = True
                    break

        if not is_overlapping:
            result_indices.append(i)
            kept_original_indices.add(parsed_rows[i]['original_index'])

    # Reconstruct the final list of rows in chronological order
    final_rows = []
    for idx in result_indices:
        row_data = parsed_rows[idx]
        final_rows.append({
            'ID': row_data['id'],
            'date': row_data['date'].strftime('%d-%b-%Y'),
            'close': row_data['close']
        })

    return final_rows

