def read_data():
    lines = """cat  val1   val2   val3   val4
A    7      10     0      19
B    10     2      1      14
C    5      15     6      16""".strip().split('\n')

    header = lines[0].split()
    data_rows = []
    for line in lines[1:]:
        parts = line.split()
        row_dict = {}
        for i, col_name in enumerate(header):
            row_dict[col_name] = float(parts[i])
        data_rows.append(row_dict)

    return data_rows

def get_column_index(headers, col_name):
    for i, h in enumerate(headers):
        if h == col_name:
            return i
    return -1

def compute_row_totals(data_rows):
    row_totals = []
    for row in data_rows:
        total = 0.0
        for key in row:
            if key != 'cat':
                total += row[key]
        row_totals.append(total)
    return row_totals

def normalize_data(data_rows, row_totals):
    normalized_rows = []
    for i, row in enumerate(data_rows):
        new_row = {}
        new_row['cat'] = row['cat']
        for key in row:
            if key != 'cat':
                total = row_totals[i]
                if total == 0.0:
                    new_row[key] = 0.0
                else:
                    new_row[key] = row[key] / total
        normalized_rows.append(new_row)
    return normalized_rows

def print_table(data_rows, headers):
    # Calculate column widths
    col_widths = {}
    for h in headers:
        max_len = len(h)
        for row in data_rows:
            val_str = str(row[h])
            if len(val_str) > max_len:
                max_len = len(val_str)
        col_widths[h] = max_len

    # Print header
    header_line = ""
    for h in headers:
        header_line += " " * (col_widths[h] - len(h)) + h
    print(header_line)

    # Print separator
    sep_line = ""
    for h in headers:
        sep_line += "-" * col_widths[h]
    print(sep_line)

    # Print rows
    for row in data_rows:
        line = ""
        for h in headers:
            val_str = str(row[h])
            padding = " " * (col_widths[h] - len(val_str))
            line += padding + val_str
        print(line)

def main():
    # Read data
    raw_data = read_data()

    # Extract headers and first row to get column names
    headers = ['cat', 'val1', 'val2', 'val3', 'val4']

    # Compute row totals
    row_totals = compute_row_totals(raw_data)

    # Normalize data
    normalized_data = normalize_data(raw_data, row_totals)

    # Print result
    print_table(normalized_data, headers)

if __name__ == "__main__":
    main()

