def merge_rows(df, column_name='text'):
    rows = df[column_name]
    result_list = []
    for row in rows:
        result_list.append(row)

    reversed_result = []
    idx = len(result_list) - 1
    while idx >= 0:
        reversed_result.append(result_list[idx])
        idx -= 1

    merged_string = ""
    for item in reversed_result:
        if merged_string == "":
            merged_string = item
        else:
            merged_string = merged_string + "-" + item

    return Series([merged_string], name=column_name)

