class DataFrame:
    def __init__(self, data_dict):
        self.data = data_dict
        self.index_list = list(data_dict.keys())

    def get_row(self, index):
        return self.data[index]

    def set_row(self, index, new_data):
        self.data[index] = new_data

    def __len__(self):
        return len(self.data)

    def __getitem__(self, key):
        if isinstance(key, int):
            return self.get_row(key)
        elif isinstance(key, str):
            return [row[key] for row in self.data.values()]
        else:
            raise TypeError("Key must be an integer or a string")

    def __setitem__(self, key, value):
        if isinstance(key, int):
            self.set_row(key, value)
        elif isinstance(key, str):
            for i in range(len(self)):
                self.data[i][key] = value[i]
        else:
            raise TypeError("Key must be an integer or a string")

    def __repr__(self):
        lines = ["A\tB\tdulplicated"]
        for idx, row in enumerate(self.data.values()):
            lines.append(f"{idx}\t{row['A']}\t{row['B']}\t{row.get('dulplicated', '')}")
        return "\n".join(lines)

def merge_dataframes(df_c, df_d):
    # Create a copy of df_c data to avoid modifying original during iteration if needed, 
    # though we are building a new structure effectively by iterating indices.
    # We need to preserve the index order of df_c and add rows from df_d that are not in df_c.

    # Map A values to B values for df_d for quick lookup without using dict comprehensions or set methods directly on lists
    d_map = {}
    for idx in range(len(df_d)):
        row = df_d.get_row(idx)
        key = row['A']
        val = row['B']
        # If key exists, overwrite (as per requirement: overwrite values in right df)
        d_map[key] = val

    result_data = {}
    result_index_list = []

    # Process rows from df_c
    for idx in range(len(df_c)):
        row = df_c.get_row(idx)
        key = row['A']

        # Check if this key exists in df_d
        is_dup = False
        if key in d_map:
            is_dup = True
            # Overwrite B value from df_d
            new_b = d_map[key]
            result_data[idx] = {
                'A': row['A'],
                'B': new_b,
                'dulplicated': is_dup
