import sys

def read_matrix_from_input():
    lines = []
    while True:
        try:
            line = sys.stdin.readline()
            if not line:
                break
            line = line.strip()
            if not line:
                continue
            parts = line.split()
            row = []
            for part in parts:
                row.append(int(part))
            lines.append(row)
        except ValueError:
            continue
    return lines

def delete_column(matrix, col_index):
    new_matrix = []
    for row in matrix:
        new_row = []
        col_count = 0
        for val in row:
