import sys

def get_max_mask_manual(matrix_str, axis):
    # Parse the input string into a list of lists of integers
    lines = matrix_str.strip().split('\n')
    matrix = []
    for line in lines:
        row = []
        parts = line.strip().split(',')
        for part in parts:
            row.append(int(part.strip()))
        matrix.append(row)

    # Validate axis
    if axis not in [0, 1]:
        raise ValueError("Axis must be 0 or 1")

    rows_count = len(matrix)
    cols_count = len(matrix[0])

    # Initialize result mask with False
    mask = []
    for i in range(rows_count):
        row_mask = []
        for j in range(cols_count):
            row_mask.append(False)
        mask.append(row_mask)

    if axis == 1:
        # Find max along axis 1 (columns) for each row
        for r in range(rows_count):
            current_max = -sys.maxsize - 1
            for c in range(cols_count):
                val = matrix[r][c]
                if val > current_max:
                    current_max = val

            # Set mask to True where value equals current_max
            for c in range(cols_count):
                if matrix[r][c] == current_max:
                    mask[r][c] = True

    elif axis == 0:
        # Find max along axis 0 (rows) for each column
        for c in range(cols_count):
            current_max = -sys.maxsize - 1
            for r in range(rows_count):
                val = matrix[r][c]
                if val > current_max:
                    current_max = val

            # Set mask to True where value equals current_max
            for r in range(rows_count):
                if matrix[r][c] == current_max:
                    mask[r][c] = True

    return mask

