import sys

def read_array_from_file(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(',')
            row = []
            for part in parts:
                try:
                    val = float(part)
                    row.append(val)
                except ValueError:
                    pass
            data.append(row)
    return data

def find_max_shape(array_list):
    max_rows = 0
    max_cols = 0
    for arr in array_list:
        if len(arr) > max_rows:
            max_rows = len(arr)
        for row in arr:
            if len(row) > max_cols:
                max_cols = len(row)
    return (max_rows, max_cols)

def pad_array_to_shape(array, target_shape):
    target_rows, target_cols = target_shape
    current_rows = len(array)
    current_cols = 0
    for row in array:
        if len(row) > current_cols:
            current_cols = len(row)

    padded_array = []
    rows_to_add = target_rows - current_rows

    for i in range(current_rows):
        new_row = []
        original_row = array[i]
        cols_to_add = target_cols - len(original_row)

        for j in range(len(original_row)):
            new_row.append(original_row[j])

        while len(new_row) < target_cols:
            new_row.append(0.0)

        padded_array.append(new_row)

    while len(padded_array) < target_rows:
        new_row = []
        for _ in range(target_cols):
            new_row.append(0.0)
        padded_array.append(new_row)

    return padded_array

def write_padded_arrays_to_file(array_list, output_filename):
    max_shape = find_max_shape(array_list)

    with open(output_filename, 'w') as f:
        for arr in array_list:
            padded_arr = pad_array_to_shape(arr, max_shape)

            for row_idx, row in enumerate(padded_arr):
                line_parts = []
                for val in row:
                    line_parts.append(str(val))
                f.write(','.join(line_parts) + '\n')

def main():
    input_filename = 'input.txt'
    output_filename = 'output_padded.txt'

    array_list = read_array_from_file(input_filename)
    write_padded_arrays_to_file(array_list, output_filename)
    print("Padding complete. Output written to " + output_filename)

