import numpy as np

def crop_zeros(image):
    # Convert input to numpy array if it isn't already, though the prompt implies it is
    arr = image

    rows = len(arr)
    cols = len(arr[0])

    # Initialize top and bottom boundaries
    top = 0
    bottom = rows - 1

    # Initialize left and right boundaries
    left = 0
    right = cols - 1

    # Find the first row from the top that contains a non-zero value
    while top <= bottom:
        current_row = arr[top]
        has_non_zero = False
        for val in current_row:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            top += 1
        else:
            break

    # Find the first row from the bottom that contains a non-zero value
    while bottom >= top:
        current_row = arr[bottom]
        has_non_zero = False
        for val in current_row:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            bottom -= 1
        else:
            break

    # Find the first column from the left that contains a non-zero value
    while left <= right:
        current_col = []
        for r in range(rows):
            current_col.append(arr[r][left])

        has_non_zero = False
        for val in current_col:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            left += 1
        else:
            break

    # Find the first column from the right that contains a non-zero value
    while right >= left:
        current_col = []
        for r in range(rows):
            current_col.append(arr[r][right])

        has_non_zero = False
        for val in current_col:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            right -= 1
        else:
            break

    # Extract the sub-array based on calculated boundaries
    result = []
    for r in range(top, bottom + 1):
        new_row = []
        for c in range(left, right + 1):
            new_row.append(arr[r][c])
        result.append(new_row)

    return result

