            row.append(False)
        visited.append(row)

    region_count = 0

    def get_neighbors(x, y):
        neighbors = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx = x + dx
                ny = y + dy
                if 0 <= nx < 512 and 0 <= ny < 512:
                    neighbors.append((nx, ny))
        return neighbors

    def flood_fill(start_x, start_y):
        stack = [(start_x, start_y)]
        while len(stack) > 0:
            curr_x, curr_y = stack[-1]
            stack.pop()

            if visited[curr_y][curr_x]:
                continue

            if grid[curr_y][curr_x] <= threshold:
                continue

            visited[curr_y][curr_x] = True

            neighbors = get_neighbors(curr_x, curr_y)
            for nx, ny in neighbors:
                stack.append((nx, ny))

    for y in range(512):
        for x in range(512):
            if not visited[y][x]:
                if grid[y][x] > threshold:
                    region_count += 1
                    flood_fill(x, y)

    return region_count

def main():
    lines = read_input_data()
    grid = build_grid(lines)
    threshold = 0.75
    result = count_regions(grid, threshold)
    print(result)

if __name__ == "__main__":
    main()

import sys

def test_func(x):
    return (x[0])**2+(x[1])**2

def test_grad(x):
    return [2*x[0],2*x[1]]

def dot_product(v1, v2):
    result = 0.0
    for i in range(len(v1)):
        result += v1[i] * v2[i]
    return result

def norm(v):
    squared_sum = 0.0
    for val in v:
        squared_sum += val * val
    return squared_sum ** 0.5

def line_search_manual(f, grad_f, xk, pk, args=()):
    alpha_min = 1e-8
    alpha_max = 100.0
    c1 = 1e-4
    c2 = 0.9

    def phi(alpha):
        x_new = [xk[i] + alpha * pk[i] for i in range(len(xk))]
        return f(x_new, *args)

    def grad_phi(alpha):
        x_new = [xk[i] + alpha * pk[i] for i in range(len(xk))]
        g = grad_f(x_new, *args)
        return dot_product(g, pk)

    phi_k = phi(0.0)
    grad_phi_k = grad_phi(0.0)

    if grad_phi_k > c1 * dot_product(pk, pk):
        return 0.0

    alpha = 1.0
    while alpha < alpha_max:
        phi_alpha = phi(alpha)
        grad_phi_alpha = grad_phi(alpha)

        if phi_alpha <= phi_k + c2 * alpha * grad_phi_k:
            return alpha

        alpha *= 2.0

    return alpha_max

xk = [1.8, 1.7]
pk = [-1.0, -1.0]

alpha_result = line_search_manual(test_func, test_grad, xk, pk)
print(alpha_result)

import math

def load_data(filename):
    values = []
    with open(filename, 'r') as file:
        for line in file:
            parts = line.split()
            if len(parts) > 1:
                try:
                    val = float(parts[1])
                    values.append(val)
                except ValueError:
                    continue
    return values

def integrate_function(c_val):
    def integrand(x):
        return 2 * x * c_val

    result = 0.0
    error = 0.0

    a = 0.0
    b = 1.0

    n_steps = 10000
    h = (b - a) / n_steps

    for i in range(n_steps):
        x_mid = a + (i + 0.5) * h
        result += integrand(x_mid) * h

    return result, error

def main():
    filename = 'cooltemp.dat'

    c_values = load_data(filename)

    if len(c_values) == 0:
        print("No valid data found in the file.")
        return

    results = []

    for n in range(len(c_values)):
        c_current = c_values[n]
        integral_result, _ = integrate_function(c_current)
        results.append(integral_result)

    output_array = []
    for i in range(len(results)):
        output_array.append(results[i])

    print("Calculated integrals:")
    for val in output_array:
        print(val)

