def matrix_to_binary(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    result = []

    for i in range(rows):
        new_row = []
        for j in range(cols):
            value = matrix[i][j]
            if value > 0:
                new_row.append(1)
            else:
                new_row.append(0)
        result.append(new_row)

    return result

