import math

def euclidean_distance_sq(vec1, vec2):
    dist_sq = 0.0
    for i in range(len(vec1)):
        diff = vec1[i] - vec2[i]
        dist_sq += diff * diff
    return dist_sq

def compute_centroid(cluster_indices, data_matrix):
    if len(cluster_indices) == 0:
        return None

    num_features = len(data_matrix[0])
    centroid = [0.0] * num_features

    for idx in cluster_indices:
        sample_vec = data_matrix[idx]
        for f in range(num_features):
            centroid[f] += sample_vec[f]

    count = len(cluster_indices)
    final_centroid = []
    for f in range(num_features):
        val = 0.0
        for c in range(count):
            val += centroid[f]
        final_centroid.append(val / count)

    return final_centroid

def find_closest_to_centroid(cluster_indices, data_matrix, cluster_centroid):
    if len(cluster_indices) == 0:
        return None

    best_idx = cluster_indices[0]
    min_dist_sq = euclidean_distance_sq(data_matrix[best_idx], cluster_centroid)

    for idx in cluster_indices:
        dist_sq = euclidean_distance_sq(data_matrix[idx], cluster_centroid)
        if dist_sq < min_dist_sq:
            min_dist_sq = dist_sq
            best_idx = idx

    return data_matrix[best_idx]

def extract_closest_to_centroids_per_cluster(cluster_labels, data_matrix):
    num_clusters = 0
    for label in cluster_labels:
        if label >= num_clusters:
            num_clusters = label + 1

    result = []

    for c in range(num_clusters):
        cluster_indices = []
        for idx in range(len(cluster_labels)):
            if cluster_labels[idx] == c:
                cluster_indices.append(idx)

        if len(cluster_indices) == 0:
            result.append(None)
            continue

        centroid = compute_centroid(cluster_indices, data_matrix)
        closest_vec = find_closest_to_centroid(cluster_indices, data_matrix, centroid)
        result.append(closest_vec)

    return result

