def find_relative_extrema(arr, n):
    length = len(arr)
    if length == 0:
        return []

    # Handle edge case where window size exceeds array bounds
    effective_n = min(n, length - 1)

    result_indices = []

    for i in range(length):
        is_extrema = True

        # Check backwards neighbors from distance 1 to n
        for dist in range(1, effective_n + 1):
            if i - dist < 0:
                break
            neighbor_val = arr[i - dist]
            current_val = arr[i]
            if neighbor_val > current_val:
                is_extrema = False
                break

        if not is_extrema:
            continue

        # Check forwards neighbors from distance 1 to n
        for dist in range(1, effective_n + 1):
            if i + dist >= length:
                break
            neighbor_val = arr[i + dist]
            current_val = arr[i]
            if neighbor_val > current_val:
                is_extrema = False
                break

        if is_extrema:
            result_indices.append(i)

    return result_indices

import statistics

def calculate_mean(values):
    total = 0.0
    count = 0
    for val in values:
        total += val
        count += 1
    if count == 0:
        return 0.0
    return total / count

def calculate_std_dev(values, mean_val):
    sum_sq_diff = 0.0
    count = 0
    for val in values:
        diff = val - mean_val
        sum_sq_diff += diff * diff
        count += 1
    if count == 0:
        return 0.0
    variance = sum_sq_diff / count
    return variance ** 0.5

def calculate_zscore(val, mean_val, std_dev):
    if std_dev == 0.0:
        return 0.0
    return (val - mean_val) / std_dev

def get_numeric_columns(df_dict):
    numeric_cols = []
    for key in df_dict:
        col_values = df_dict[key]
        is_numeric = True
        for val in col_values:
            if not isinstance(val, (int, float)):
                is_numeric = False
                break
        if is_numeric:
            numeric_cols.append(key)
    return numeric_cols

def remove_outliers(df_dict, threshold=3.0):
    numeric_cols = get_numeric_columns(df_dict)

    if len(numeric_cols) == 0:
        return df_dict

    means = {}
    std_devs = {}

    for col in numeric_cols:
        values = df_dict[col]
        mean_val = calculate_mean(values)
        std_dev = calculate_std_dev(values, mean_val)
        means[col] = mean_val
        std_devs[col] = std_dev

    keep_indices = []

    for i in range(len(df_dict[next(iter(df_dict))])):
        is_outlier = False

        for col in numeric_cols:
            val = df_dict[col][i]
            mean_val = means[col]
            std_dev = std_devs[col]

            z = calculate_zscore(val, mean_val, std_dev)

            if abs(z) > threshold:
                is_outlier = True
                break

        if not is_outlier:
            keep_indices.append(i)

    new_df_dict = {}
    for key in df_dict:
        new_col_values = []
        for idx in keep_indices:
            new_col_values.append(df_dict[key][idx])
        new_df_dict[key] = new_col_values

    return new_df_dict

