# Define a simple Pipeline class from scratch
class SimplePipeline:
    def __init__(self, steps):
        self.steps = steps
        self.named_steps = {}
        for step_name, transformer in steps:
            self.named_steps[step_name] = transformer

    def fit_transform(self, data):
        current_data = data

        # Iterate through steps manually
        for step_name, transformer in self.steps:
            # Apply the transformer to the current data
            current_data = transformer.fit_transform(current_data)

        return current_data

