def convert_to_binary_matrix(feature_list):
    # Step 1: Extract all unique features and sort them manually
    all_features = []
    for feature_set in feature_list:
        for item in feature_set:
            if item not in all_features:
                all_features.append(item)

    # Sort the unique features manually using bubble sort
    n_features = len(all_features)
    for i in range(n_features):
        for j in range(0, n_features - i - 1):
            if all_features[j] > all_features[j + 1]:
                temp = all_features[j]
                all_features[j] = all_features[j + 1]
                all_features[j + 1] = temp

    # Step 2: Create the binary matrix manually
    num_samples = len(feature_list)
    binary_matrix = []

    for sample_idx in range(num_samples):
        current_sample = feature_list[sample_idx]
        row = []

        for feature_idx in range(n_features):
            target_feature = all_features[feature_idx]
            # Check if the target feature exists in the current sample
            found = False
            for item in current_sample:
                if item == target_feature:
                    found = True
                    break

            if found:
                row.append(1)
            else:
                row.append(0)

        binary_matrix.append(row)

    return binary_matrix, all_features

