import math

def read_data_from_file(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            parts = line.strip().split(',')
            row = []
            for part in parts:
                try:
                    val = float(part)
                    row.append(val)
                except ValueError:
                    continue
            if len(row) > 0:
                data.append(row)
    return data

def calculate_mean(values):
    total = 0.0
    count = 0
    for v in values:
        total += v
        count += 1
    if count == 0:
        return 0.0
    return total / count

def calculate_std_dev(values, mean_val):
    sum_sq_diff = 0.0
    count = 0
    for v in values:
        diff = v - mean_val
        sum_sq_diff += diff * diff
        count += 1
    if count == 0:
        return 0.0
    variance = sum_sq_diff / count
    return math.sqrt(variance)

def scale_and_center_data(data):
    if not data or len(data[0]) == 0:
        return []

    num_cols = len(data[0])
    scaled_data = []

    for col_idx in range(num_cols):
        column_values = []
        for row in data:
            if col_idx < len(row):
                column_values.append(row[col_idx])

        mean_val = calculate_mean(column_values)
        std_dev = calculate_std_dev(column_values, mean_val)

        if std_dev == 0.0:
            continue

        for row in data:
            if col_idx < len(row):
                original_val = row[col_idx]
                scaled_val = (original_val - mean_val) / std_dev
                row[col_idx] = scaled_val

    return data

def main():
    filename = "data.csv"
    try:
        raw_data = read_data_from_file(filename)
        if not raw_data:
            print("No valid data found.")
            return

        processed_data = scale_and_center_data(raw_data)

        with open("scaled_data.csv", 'w') as f:
            for row in processed_data:
                line = ",".join(str(x) for x in row)
                f.write(line + "\n")

        print("Data scaling and centering completed successfully.")
    except FileNotFoundError:
        print(f"File {filename} not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

import random

def manual_read_csv(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            if line.strip() == '':
                continue
            row = []
            current_num = ''
            for char in line:
                if char == ',':
                    row.append(int(current_num))
                    current_num = ''
                else:
                    current_num += char
            if current_num != '':
                row.append(int(current_num))
            data.append(row)
    return data

def manual_split_data(data, train_ratio):
    random.shuffle(data)
    split_index = int(len(data) * train_ratio)
    training_set = data[:split_index]
    testing_set = data[split_index:]
    return training_set, testing_set

def separate_features_and_labels(dataset_list):
    x_list = []
    y_list = []
    for row in dataset_list:
        if len(row) == 0:
            continue
        feature_row = row[:-1]
        label = row[-1]
        x_list.append(feature_row)
        y_list.append(label)
    return x_list, y_list

def manual_sum(lst):
    total = 0
    for item in lst:
        total += item
    return total

def manual_max(lst):
    if len(lst) == 0:
        return None
    current_max = lst[0]
    for i in range(1, len(lst)):
