import re

def tokenize(text):
    tokens = []
    current_token = ""

    for char in text:
        if char.isalnum() or char == '@' or char == '#':
            current_token += char
        else:
            if current_token:
                tokens.append(current_token)
                current_token = ""

    if current_token:
        tokens.append(current_token)

    return tokens

def count_vectorizer(words_list):
    vocabulary = {}
    counts = []

    for words in words_list:
        tokenized_words = tokenize(words)
        word_counts = {}

        for token in tokenized_words:
            if token in word_counts:
                word_counts[token] += 1
            else:
                word_counts[token] = 1

        count_list = []
        for key in vocabulary.keys():
            count_list.append(word_counts.get(key, 0))

        counts.append(count_list)

        for token in word_counts.keys():
            if token not in vocabulary:
                vocabulary[token] = len(vocabulary)

    feature_names = list(vocabulary.keys())

    return feature_names, counts

