        abs_x = manual_tensor_abs(x)[i]
        abs_y = manual_tensor_abs(y)[i]
        mx = manual_max(abs_x, abs_y)
        max_vals.append(mx)
        i += 1
    return max_vals

def manual_select_and_sign(x, y):
    x_len = len(x)
    y_len = len(y)
    min_len = manual_min_len(x_len, y_len)

    result = []
    i = 0
    while i < min_len:
        val_x = x[i]
        val_y = y[i]

        abs_x = manual_abs(val_x)
        abs_y = manual_abs(val_y)

        max_val = manual_max(abs_x, abs_y)

        if abs_x >= abs_y:
            result.append(val_x)
        else:
            result.append(val_y)

        i += 1

    return result

def main():
    # Example usage with lists representing tensors
    x = [3.0, -5.0, 2.0]
    y = [-4.0, 6.0, 1.0]

    selected = manual_select_and_sign(x, y)

    print("Selected elements:", selected)

if __name__ == "__main__":
    main()

import math

def manual_sign(value):
    if value > 0:
        return 1
    elif value < 0:
        return -1
    else:
        return 0

def manual_abs(value):
    if value >= 0:
        return value
    else:
        return -value

def manual_min(a, b):
    if a <= b:
        return a
    else:
        return b

def manual_max(a, b):
    if a >= b:
        return a
    else:
        return b

def manual_index_of_min(values_list):
    min_val = values_list[0]
    min_idx = 0
    for i in range(1, len(values_list)):
        if values_list[i] < min_val:
            min_val = values_list[i]
            min_idx = i
    return min_idx

def manual_index_of_max(values_list):
    max_val = values_list[0]
    max_idx = 0
    for i in range(1, len(values_list)):
        if values_list[i] > max_val:
            max_val = values_list[i]
            max_idx = i
    return max_idx

def manual_sum(values_list):
    total = 0
    for val in values_list:
        total += val
    return total

def manual_product(values_list):
    result = 1
    for val in values_list:
        result *= val
    return result

def manual_len(lst):
    count = 0
    for _ in lst:
        count += 1
    return count

def manual_copy(source, target):
    for i in range(manual_len(source)):
        target[i] = source[i]

def manual_tensor_init(size):
    result = []
    for i in range(size):
        result.append(0)
    return result

def manual_abs_tensor(tensor):
    result = manual_tensor_init(manual_len(tensor))
    for i in range(manual_len(tensor)):
        result[i] = manual_abs(tensor[i])
    return result

def manual_sign_tensor(tensor):
    result = manual_tensor_init(manual_len(tensor))
    for i in range(manual_len(tensor)):
        result[i] = manual_sign(tensor[i])
    return result

def manual_min_tensor(tensor1, tensor2):
    abs1 = manual_abs_tensor(tensor1)
    abs2 = manual_abs_tensor(tensor2)
    result = manual_tensor_init(manual_len(tensor1))
    for i in range(manual_len(tensor1)):
        result[i] = manual_min(abs1[i], abs2[i])
    return result

def manual_select_source_based_on_abs_diff(tensor1, tensor2):
    abs1 = manual_abs_tensor(tensor1)
    abs2 = manual_abs_tensor(tensor2)
    diff = manual_tensor_init(manual_len(tensor1))
    for i in range(manual_len(tensor1)):
        diff[i] = abs1[i] - abs2[i]

    result = manual_tensor_init(manual_len(tensor1))
    for i in range(manual_len(tensor1)):
        if diff[i] <= 0:
            result[i] = tensor1[i]
        else:
            result[i] = tensor2[i]
    return result

def manual_sign_and_min_abs(x, y):
    sign_x = manual_sign_tensor(x)
    sign_y = manual_sign_tensor(y)

    abs_x = manual_abs_tensor(x)
    abs_y = manual_abs_tensor(y)

    min_abs = manual_min_tensor(abs_x, abs_y)

    result = manual_tensor_init(manual_len(x))
    for i in range(manual_len(x)):
        if abs_x[i] <= abs_y[i]:
            result[i] = sign_x[i] * min_abs[i]
        else:
            result[i] = sign_y[i] * min_abs[i]

    return result

def manual_tensor_print(tensor):
    print("[", end="")
    for i in range(manual_len(tensor)):
        if i > 0:
            print(", ", end="")
        print(tensor[i], end="")
    print("]")

# Example usage
if __name__ == "__main__":
    # Simulating tensors as lists of floats
    x = [3.5, -2.1, 4.0, -1.5]
    y = [-3.0, 2.5, 1.0, -2.0]

    print("Input X:", end=" ")
    manual_tensor_print(x)
    print("Input Y:", end=" ")
    manual_tensor_print(y)

    result = manual_sign_and_min_abs(x, y)
    print("Result (min abs with sign):", end=" ")
    manual_tensor_print(result)
